// The candlestick chart is the level. It is generated from a seed, one block per take-profit gate,
// so the same seed (e.g. today's date) always gives the same chart.
//
// The player rides the top of each candle body. Most candles are small, so the board glides over them;
// the things that need a jump are spaced by time: how far the player travels in the quiet seconds
// that block allows. Those seconds shrink block by block, so the chart keeps getting harder.
import {
  AIR_TIME,
  ARMED_FROM,
  ARMED_MIX,
  BAG_HEIGHTS,
  BOSS_BACK,
  BOSS_H,
  BOSS_W,
  CEIL_WINDOW,
  calmTime,
  DIVE_AIR,
  EVENT_CHANCE,
  EVENT_FROM,
  EVENT_MIX,
  FLYER_FROM,
  FLYER_H,
  FLYER_HIGH,
  FLYER_LOW,
  FUD_HEIGHT,
  GAP_SINK,
  GATE_EVERY,
  GATE_FIRST,
  GATE_PAD_AFTER,
  GATE_PAD_BEFORE,
  GRAVITY,
  GUN_AIR,
  HOP_AIR,
  ITEM_HEIGHT,
  type ItemKind,
  type MarketEvent,
  marketSpeed,
  PAIR_AIR,
  type Phase,
  ROCKET_CEIL,
  SKY_COIN_ALT,
  SKY_LEN,
  SPOUT_AIR,
  SPOUT_HALF,
  SQUAD_FROM,
  SQUAD_MIX,
  type Squad,
  STAIR_AIR,
  STEP,
  STORM_CALM,
  STORM_ROW,
  STORM_TALL,
  speedAt,
  WHALE_BACK,
  WHALE_BLOWHOLE,
  WHALE_CHANCE,
  WHALE_DEPTH,
  WHALE_DUE,
  WHALE_LEN,
  WHALE_RISE,
  WHALE_SPOUT,
} from './data.ts';
import { makeRng, type Rng } from './rng.ts';

export interface Coin {
  x: number;
  y: number;
  /** a moon coin: hidden at the top of the sky and over the whale's spout, worth much more */
  moon?: boolean;
  /** an airdropped money bag: it comes down on a parachute and pays much more than a coin */
  bag?: boolean;
}

export type Feature = 'wall' | 'drop' | 'spike' | 'gap' | 'fud' | 'bear' | 'paw' | 'flyer';

/** a stretch of the chart where something special happens */
export type ChartEvent = 'whale';

export interface Candle {
  i: number;
  /** a liquidity gap: there is no candle here */
  gap: boolean;
  /** body; the player rides `top`. For a gap, `top` is the level of the edge before it. */
  top: number;
  bottom: number;
  green: boolean;
  /** wick ends, decoration only */
  high: number;
  low: number;
  /** a long upper wick that hurts: height above `top`, 0 = none */
  spike: number;
  /** FUD cloud: height of its centre above `top`, 0 = none */
  fud: number;
  /** a bear (short seller) stands here: a hit from the side, a short squeeze when landed on */
  bear: boolean;
  /** a paw of the big bear hangs low over this crack: whoever jumps high under it gets swatted */
  paw: boolean;
  /**
   * a jet meets the player over this candle: the height of its underside above `top`, 0 = none.
   * Where it is before and after that depends on where the player is (see flyerX).
   */
  flyer: number;
  /** the first candle of a formation of jets says which formation it is */
  squad: Squad | null;
  /**
   * a bullet meets the player over this candle, low: the number is how many candles later the jet
   * that fired it passes overhead, 0 = none (see bulletX)
   */
  bullet: number;
  /** a gap that is bombed out of the chart as the player comes near: until then a candle stands here */
  crater: boolean;
  /** the big bear lies here and on the next candle: a hit from the side, a big squeeze from above */
  boss: boolean;
  /** part of a whale stretch: the water, the whale's back and the far bank */
  event: ChartEvent | null;
  /** the whale's back: whatever lands here bounces */
  bounce: boolean;
  /** the whale's blowhole: the highest bounce of all */
  spout: boolean;
  /** the market event this candle is part of, if any */
  market: MarketEvent | null;
  coins: Coin[];
  item: ItemKind | null;
  /** take-profit gate standing on the middle of this candle */
  gate: boolean;
  phase: Phase;
  /** what needs attention here, for tests and the tutorial */
  feature: Feature | null;
  /** volume bar under the chart, 0..1, decoration only */
  vol: number;
}

interface Slot {
  delta: number;
  gap: boolean;
  spike: number;
  fud: boolean;
  bear: boolean;
  paw: boolean;
  flyer: number;
  squad: Squad | null;
  bullet: number;
  crater: boolean;
  boss: boolean;
  event: ChartEvent | null;
  bounce: boolean;
  spout: boolean;
  feature: Feature | null;
  /** free of features and of the gate, so coins and items may go here */
  open: boolean;
  item: ItemKind | null;
  gate: boolean;
}

const DRIFT: Record<Phase, [drift: number, jitter: number]> = {
  sideways: [0, 0.18],
  bull: [0.12, 0.15],
  bear: [-0.14, 0.15],
  pump: [0.2, 0.1],
  crash: [-0.22, 0.15],
};

/** how often each feature shows up in a phase */
const MIX: Record<Phase, Partial<Record<Feature, number>>> = {
  sideways: { spike: 3, fud: 2, gap: 2, wall: 1, drop: 1, bear: 1.5, flyer: 5 },
  bull: { wall: 4, spike: 2, fud: 1, gap: 1, flyer: 4 },
  bear: { drop: 2, gap: 3, fud: 2, spike: 2, bear: 4, flyer: 6.5 },
  pump: { wall: 6, spike: 1.5, flyer: 3.5 },
  crash: { drop: 3, gap: 3, spike: 2, fud: 1, bear: 2, flyer: 5.5 },
};

/** a wick storm: nothing but wicks */
const WICK_MIX: Partial<Record<Feature, number>> = { spike: 1 };
/** a bear market: paws from above, cracks in the ground, and big red candles */
const BEAR_MIX: Partial<Record<Feature, number>> = { paw: 6, gap: 1, drop: 1 };

const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));

/** the gate index of block k */
export const gateIndex = (k: number): number => GATE_FIRST + GATE_EVERY * k;

/** the block that candle i belongs to */
export const blockOf = (i: number): number => {
  const first = GATE_FIRST + GATE_PAD_AFTER + 1;
  return i < first ? 0 : 1 + Math.floor((i - first) / GATE_EVERY);
};

/** the widest liquidity gap a single jump can cross at this speed, with room to spare */
export const maxGapWidth = (speed: number): number =>
  clamp(Math.floor(speed * AIR_TIME - 0.8), 1, 3);

/**
 * The narrowest gap that riding on cannot carry across at this speed: by the far edge the rider
 * has sunk more than the board glides up (STEP), with GAP_SINK to spare. The faster, the wider.
 */
export const minGapWidth = (speed: number): number =>
  Math.floor(speed * Math.sqrt((2 * (STEP + GAP_SINK)) / GRAVITY)) + 1;

/**
 * How far below the near edge the far edge of a gap may lie, up to `most`: a lower far edge is
 * easier to be carried onto, so it is only as low as still leaves the rider below it.
 */
export const farEdgeDrop = (width: number, speed: number, most: number): number =>
  clamp((GRAVITY / 2) * (width / speed) ** 2 - STEP - GAP_SINK / 2, 0, most);

/** the widest crack the shortest hop crosses with room to spare: what a paw may hang over */
export const hopGapWidth = (speed: number): number =>
  clamp(Math.floor(speed * HOP_AIR - 0.7), 1, 2);

/**
 * How many candles after the first thing of a formation the second one meets the player.
 * A pair is one bounce apart and a stair is where the bounce comes down on the higher one, so both
 * can be squeezed in a row; in a dive the low one is right behind the high one. A gunner's jet comes
 * this long after its bullet, and a bomber's gap this long after the bomber.
 */
export const squadGap = (squad: Squad, speed: number): number =>
  squad === 'single'
    ? 0
    : squad === 'pair'
      ? Math.max(2, Math.round(speed * PAIR_AIR))
      : squad === 'stair'
        ? Math.max(2, Math.round(speed * STAIR_AIR))
        : squad === 'gunner'
          ? Math.max(2, Math.round(speed * GUN_AIR))
          : Math.max(2, Math.ceil(speed * DIVE_AIR));

/** candles left quiet after a hazard in block k: what the player covers in that block's calm time */
export const restAfter = (speed: number, k: number): number =>
  Math.max(2, Math.ceil(speed * calmTime(k)));

/** candles left quiet after a hazard in a wick storm: never more than the storm's own short calm */
export const stormRest = (speed: number, k: number): number =>
  Math.min(restAfter(speed, k), Math.max(2, Math.ceil(speed * STORM_CALM)));

/** candles kept clear after the far end of the whale's spout, so it sets the player down on quiet ground */
export const spoutLanding = (speed: number): number => Math.ceil(speed * SPOUT_AIR) + 2;

export class Chart {
  readonly candles: Candle[] = [];
  private readonly rng: Rng;
  private blocks = 0;
  private level = 0;
  private lastPhase: Phase = 'sideways';
  private lastRocket = -9;
  private lastWhale = -1;
  private lastMarket = -9;
  /** candles [skyFrom, skyTo) carry coins in the sky, for whoever took the rocket */
  private skyFrom = 0;
  private skyTo = 0;

  /**
   * @param first for trying things out: the first block that may have a market event has this one
   *   (the rest of the chart is laid out from the same random numbers as without it)
   */
  constructor(
    readonly seed: number,
    private readonly first: MarketEvent | null = null,
  ) {
    this.rng = makeRng(seed);
  }

  at(i: number): Candle {
    while (this.candles.length <= i) this.addBlock();
    return this.candles[i];
  }

  /** first candle at or after i that is not a gap */
  solidFrom(i: number): Candle {
    let c = this.at(Math.max(0, i));
    while (c.gap) c = this.at(c.i + 1);
    return c;
  }

  /** last candle at or before i that is not a gap */
  solidUpTo(i: number): Candle {
    let j = Math.max(0, i);
    while (j > 0 && this.at(j).gap) j--;
    return this.at(j);
  }

  /** the top of the sky over candle i: a rocket cannot climb past it, and the moon coins hang there */
  ceiling(i: number): number {
    let top = Number.NEGATIVE_INFINITY;
    for (let j = Math.max(0, i - CEIL_WINDOW); j <= i; j++) top = Math.max(top, this.at(j).top);
    return top + ROCKET_CEIL;
  }

  private int(n: number): number {
    return Math.floor(this.rng() * n);
  }

  private pickPhase(k: number): Phase {
    if (k === 0) return 'sideways';
    if (k === 1) return 'bull';
    const w: [Phase, number][] = [
      ['sideways', 3],
      ['bull', 3],
      ['bear', 3],
      ['pump', this.lastPhase === 'pump' ? 0 : 1.5],
      ['crash', this.lastPhase === 'crash' ? 0 : 1.2],
    ];
    let r = this.rng() * w.reduce((a, [, n]) => a + n, 0);
    for (const [p, n] of w) {
      r -= n;
      if (r < 0) return p;
    }
    return 'sideways';
  }

  private pickFeature(phase: Phase, market: MarketEvent | null): Feature {
    const mix = market === 'wicks' ? WICK_MIX : market === 'bearmarket' ? BEAR_MIX : MIX[phase];
    const list = Object.entries(mix) as [Feature, number][];
    let r = this.rng() * list.reduce((a, [, n]) => a + n, 0);
    for (const [f, n] of list) {
      r -= n;
      if (r < 0) return f;
    }
    return list[0][0];
  }

  private addBlock(): void {
    const k = this.blocks++;
    const rng = this.rng;
    const start = this.candles.length;
    // a market event may take over the whole block; it also sets the trend
    let market: MarketEvent | null = null;
    if (k >= EVENT_FROM) {
      const roll = rng();
      let pick = rng() * EVENT_MIX.reduce((a, [, n]) => a + n, 0);
      if (k - this.lastMarket >= 2 && roll < EVENT_CHANCE) {
        this.lastMarket = k;
        market = EVENT_MIX[0][0];
        for (const [m, n] of EVENT_MIX) {
          pick -= n;
          if (pick < 0) {
            market = m;
            break;
          }
        }
      }
      if (k === EVENT_FROM && this.first) {
        this.lastMarket = k;
        market = this.first;
      }
    }
    const phase: Phase =
      market === 'exit'
        ? 'bear'
        : market === 'bearmarket'
          ? 'crash'
          : market === 'boost' || market === 'megaboost'
            ? 'bull'
            : market === 'wicks'
              ? 'sideways'
              : this.pickPhase(k);
    this.lastPhase = phase;
    const F =
      k === 0 ? GATE_FIRST - GATE_PAD_BEFORE : GATE_EVERY - GATE_PAD_BEFORE - GATE_PAD_AFTER - 1;
    const n = F + GATE_PAD_BEFORE + 1 + GATE_PAD_AFTER;
    const [drift, jitter] = DRIFT[phase];

    const slots: Slot[] = [];
    for (let s = 0; s < n; s++) {
      const pad = s >= F;
      slots.push({
        delta: pad
          ? (rng() * 2 - 1) * 0.08
          : clamp(drift + (rng() * 2 - 1) * jitter, -0.6, STEP - 0.05),
        gap: false,
        spike: 0,
        fud: false,
        bear: false,
        paw: false,
        flyer: 0,
        squad: null,
        bullet: 0,
        crater: false,
        boss: false,
        event: null,
        bounce: false,
        spout: false,
        feature: null,
        open: !pad,
        item: null,
        gate: s === F + GATE_PAD_BEFORE,
      });
    }

    const speed = speedAt(start) * marketSpeed(market);
    // (the run is a little faster by the end of the block: gaps are sized for that)
    const speedOut = speedAt(start + n) * marketSpeed(market);
    const leastGap = minGapWidth(speedOut);
    // (while big money sells out the chart runs faster: one more quiet candle between hazards)
    const rest =
      market === 'wicks' ? stormRest(speed, k) : restAfter(speed, k) + (market === 'exit' ? 1 : 0);
    // a little extra room in the early blocks, none later
    const packed = market === 'bearmarket' || market === 'wicks';
    const spare = packed ? 0 : k < 3 ? 2 : k < 6 ? 1 : 0;
    const close = (s: number) => {
      if (slots[s]) slots[s].open = false;
    };
    const calm = (s: number) => {
      if (slots[s]) slots[s].delta = (rng() * 2 - 1) * 0.03;
    };

    // one pickup per block; a rocket sits at the start of its block
    let item: ItemKind | null = null;
    if (k >= 1) {
      const r = rng();
      item = r < 0.5 ? 'margin' : r < 0.8 ? 'shield' : 'rocket';
      if (item === 'rocket' && (k < 2 || k - this.lastRocket < 2)) item = 'margin';
    }
    // stretches the hazards keep out of: a hazard that would start in [from, to) moves to `to`
    const zones: { from: number; to: number }[] = [];
    if (item === 'rocket') {
      this.lastRocket = k;
      slots[1].item = 'rocket';
      for (let s = 0; s <= 2; s++) {
        close(s);
        calm(s);
      }
      this.skyFrom = start + 4;
      this.skyTo = start + 4 + SKY_LEN;
    }

    // A whale's order eats the liquidity. Water, the whale's back, water, and the far bank a little
    // higher: the back is the only way across, and whatever lands on it bounces.
    let whaleAt = -1;
    if (k >= 1) {
      const roll = rng();
      const due = k - this.lastWhale >= WHALE_DUE;
      // (a bear market and a wick storm fill their block themselves)
      const free = item !== 'rocket' && !packed;
      if (free && k - this.lastWhale >= 2 && (roll < WHALE_CHANCE || due)) {
        this.lastWhale = k;
        const land = spoutLanding(speed);
        const lo = rest + 3;
        const hi = F - WHALE_LEN - land;
        const at = lo + this.int(Math.max(1, hi - lo + 1));
        whaleAt = at;
        for (let s = at; s < at + WHALE_LEN; s++) {
          slots[s].event = 'whale';
          slots[s].delta = 0;
          close(s);
        }
        slots[at].gap = true;
        slots[at + WHALE_BACK + 1].gap = true;
        for (let s = at + 1; s <= at + WHALE_BACK; s++) slots[s].bounce = true;
        slots[at + 1 + WHALE_BLOWHOLE].spout = true;
        slots[at + 1].delta = -WHALE_DEPTH;
        slots[at + WHALE_BACK + 2].delta = WHALE_DEPTH + WHALE_RISE;
        // flat banks on both sides, and a clear run where the blowhole sets the player down
        for (const s of [at - 2, at - 1]) {
          calm(s);
          close(s);
        }
        const to = at + 2 + WHALE_BLOWHOLE + SPOUT_HALF + land;
        for (let s = at + WHALE_LEN; s < to; s++) {
          if (s < F) calm(s);
          close(s);
        }
        zones.push({ from: at - rest - 2, to: Math.max(to, at + WHALE_LEN + 2) });
      }
    }

    // a bear market ends with the big bear itself, lying across two candles. Nothing comes after it
    // but quiet ground, so the bounce off its head comes down well before the gate.
    let bossAt = -1;
    if (market === 'bearmarket') {
      bossAt = F - BOSS_BACK;
      slots[bossAt].boss = true;
      for (let s = bossAt - 2; s <= bossAt + BOSS_W + 1; s++) {
        calm(s);
        close(s);
      }
      zones.push({ from: bossAt - rest - 2, to: F });
    }

    if (k === 0) {
      // a gentle start: flat, then one small wall and one short spike
      for (let s = 0; s < 7; s++) calm(s);
      slots[8].delta = 0.8;
      slots[8].feature = 'wall';
      slots[13].spike = 0.8;
      slots[13].feature = 'spike';
      calm(13);
      for (const s of [7, 8, 9, 12, 13, 14]) close(s);
    } else {
      let p = (item === 'rocket' ? 3 : 1) + this.int(3);
      // a margin top-up or diamond hands takes the place of one hazard, with room to land after the hop
      let itemAt = item && item !== 'rocket' ? 4 + this.int(F - 14) : -1;
      while (p < F - 2) {
        const zone = zones.find((z) => p >= z.from && p < z.to);
        if (zone) {
          p = zone.to;
          continue;
        }
        if (itemAt >= 0 && p >= itemAt && p + 3 < F) {
          slots[p + 1].item = item;
          for (let s = p; s <= p + 2; s++) {
            close(s);
            calm(s);
          }
          itemAt = -1;
          // the hop for it comes down half a jump later: the quiet stretch starts from there
          p += 2 + rest + Math.ceil((speed * AIR_TIME) / 2);
          continue;
        }
        let f = this.pickFeature(phase, market);
        // (flying bears need room before the gate)
        if (f === 'flyer' && (k < FLYER_FROM || p > F - 5)) f = 'spike';
        // (a gap or a crack that does not fit at its full width would be one that riding on crosses)
        if (f === 'gap' && F - 2 - p < leastGap) f = market === 'bearmarket' ? 'drop' : 'spike';
        if (f === 'paw' && F - 2 - p < hopGapWidth(speed)) f = 'drop';
        let width = 1;
        let extra = 0;
        // a tall wall or a tall wick takes a double jump: three more quiet, level candles to set it up
        const tall =
          k >= 2 &&
          p + 3 < F - 2 &&
          !zones.some((z) => p + 3 >= z.from && p + 3 < z.to) &&
          ((f === 'wall' && (phase === 'pump' || phase === 'bull') && rng() < 0.35) ||
            (f === 'spike' && rng() < (market === 'wicks' ? STORM_TALL : 0.3)));
        if (tall) {
          p += 3;
          calm(p - 1);
          calm(p - 2);
        }
        if (f === 'wall') {
          // level ground in front of a wall: the climb is the wall itself, not the slope before it
          calm(p - 1);
          calm(p - 2);
          slots[p].delta = tall ? 2 + rng() * 0.8 : 0.7 + rng() * 0.9;
        } else if (f === 'drop') {
          const d = phase === 'crash' ? 3.5 + rng() * 3 : 1.2 + rng() * 2;
          slots[p].delta = -d;
          // the fall takes time: leave room to land
          extra = Math.ceil(speed * Math.sqrt((2 * d) / GRAVITY) * 0.6);
        } else if (f === 'spike') {
          // one tall wick, or a row of short ones: two from the second block on, three later
          // (a wick storm has more rows, and rows of three as soon as the speed allows)
          const storm = market === 'wicks';
          const row = tall
            ? 1
            : rng() < (storm ? STORM_ROW : 0.45)
              ? (storm || k >= 5) && speed >= 8 && rng() < (storm ? 0.6 : 0.4)
                ? 3
                : 2
              : 1;
          width = Math.max(1, Math.min(row, F - 2 - p));
          for (let s = p; s < p + width; s++) {
            slots[s].spike = tall
              ? 1.7 + rng() * 0.6
              : width > 1
                ? 0.7 + rng() * (width > 2 ? 0.1 : 0.3)
                : 0.7 + rng() * 0.8;
            slots[s].feature = 'spike';
            calm(s);
          }
        } else if (f === 'paw') {
          // a crack with a paw hanging low over it: it has to be jumped, but only with a short hop
          width = hopGapWidth(speed);
          for (let s = p; s < p + width; s++) {
            slots[s].gap = true;
            slots[s].paw = true;
            slots[s].delta = 0;
            slots[s].feature = 'paw';
          }
          // level edges, the far one never the higher: the hop only has to be long enough
          calm(p - 1);
          slots[p + width].delta = -rng() * farEdgeDrop(width, speedOut, 0.05);
        } else if (f === 'flyer') {
          // the shorts' air force: one jet at first, then formations of two, then armed jets
          let squad: Squad = 'single';
          let roll = rng() * 100;
          if (k >= SQUAD_FROM)
            for (const [q, n] of k >= ARMED_FROM ? ARMED_MIX : SQUAD_MIX) {
              roll -= n;
              if (roll < 0) {
                squad = q;
                break;
              }
            }
          let g = squadGap(squad, speed);
          // (a bombed gap is as wide as a paw's crack: a hop crosses it, riding on does not)
          const hole = hopGapWidth(speed);
          if (g > 0 && (p + g > F - 7 || zones.some((z) => p + g + 4 >= z.from && p + g < z.to))) {
            squad = 'single';
            g = 0;
          }
          slots[p].squad = squad;
          width = g + (squad === 'bomber' ? hole : 1);
          // flat ground from the run-up to where the bounce off the last jet comes down
          extra = Math.ceil(speed * 0.3);
          for (let s = p - 2; s <= p + width + extra; s++) if (s < F) calm(s);
          if (squad === 'gunner') {
            // the bullet comes first, low; the jet that fired it passes overhead after it
            slots[p].bullet = g;
            slots[p + g].flyer = FLYER_HIGH;
          } else if (squad === 'bomber') {
            // the jet passes overhead, and the candle behind it is bombed out of the chart
            slots[p].flyer = FLYER_HIGH;
            for (let s = p + g; s < p + g + hole; s++) {
              slots[s].gap = true;
              slots[s].crater = true;
              slots[s].delta = 0;
              slots[s].feature = 'flyer';
            }
            // the far edge is never the higher one
            slots[p + g + hole].delta = -rng() * farEdgeDrop(hole, speedOut, 0.05);
          } else {
            slots[p].flyer = squad === 'dive' ? FLYER_HIGH : FLYER_LOW;
            if (g > 0) slots[p + g].flyer = squad === 'stair' ? FLYER_HIGH : FLYER_LOW;
          }
          if (g > 0) slots[p + g].feature = 'flyer';
        } else if (f === 'bear') {
          slots[p].bear = true;
          // flat under and around the bear, so landing on it is a matter of timing only
          for (let s = p - 1; s <= p + 1; s++) calm(s);
        } else if (f === 'gap') {
          // from the narrowest that has to be jumped to the widest a jump crosses: wider with speed
          width = leastGap + this.int(Math.max(1, maxGapWidth(speed) - leastGap + 1));
          width = Math.min(width, F - 2 - p);
          for (let s = p; s < p + width; s++) {
            slots[s].gap = true;
            slots[s].delta = 0;
            slots[s].feature = 'gap';
          }
          // the far edge is level with or a little below the near edge
          slots[p + width].delta = -rng() * farEdgeDrop(width, speedOut, 0.3);
        } else {
          const wide = 1 + (rng() < 0.4 ? 1 : 0) + (k >= 4 && rng() < 0.3 ? 1 : 0);
          width = Math.min(wide, F - 2 - p);
          for (let s = p; s < p + width; s++) {
            slots[s].fud = true;
            slots[s].feature = 'fud';
          }
          // flat under and around the cloud, so nothing lifts the player into it
          for (let s = p; s <= p + width; s++) calm(s);
        }
        slots[p].feature = f;
        for (let s = p - 1; s <= p + width; s++) close(s);
        p += width + rest + extra + this.int(spare + 1);
      }
    }

    // surfaces
    const surf: number[] = [];
    let level = this.level;
    for (const s of slots) {
      level += s.delta;
      surf.push(level);
    }
    this.level = level;

    // candles
    for (let s = 0; s < n; s++) {
      const sl = slots[s];
      const i = start + s;
      const top = surf[s];
      const prev = this.candles[i - 1];
      let next = surf[s];
      for (let q = s + 1; q < n; q++) {
        if (!slots[q].gap) {
          next = surf[q];
          break;
        }
      }
      const green = next >= top - 0.05;
      const prevClose =
        !prev || prev.gap ? top - 0.3 - rng() * 0.6 : prev.green ? prev.top : prev.bottom;
      const bottom = Math.min(top - 0.25, Math.max(green ? prevClose : next, top - 3.5));
      this.candles.push({
        i,
        gap: sl.gap,
        top,
        bottom,
        green,
        high: top + (sl.spike ? 0 : rng() * 0.14),
        low: bottom - rng() * rng() * 0.7,
        spike: sl.spike,
        fud: sl.fud ? FUD_HEIGHT : 0,
        bear: sl.bear,
        paw: sl.paw,
        flyer: sl.flyer,
        squad: sl.squad,
        bullet: sl.bullet,
        crater: sl.crater,
        boss: sl.boss,
        event: sl.event,
        bounce: sl.bounce,
        spout: sl.spout,
        market: s < F ? market : null,
        coins: [],
        item: sl.item,
        gate: sl.gate,
        phase,
        feature: sl.feature,
        vol: clamp(0.15 + Math.abs(sl.delta) * 0.35 + rng() * 0.3, 0.05, 1),
      });
    }

    this.addCoins(start, slots, surf, speed, whaleAt, market ? F : 0, market, bossAt);
  }

  private addCoins(
    start: number,
    slots: Slot[],
    surf: number[],
    speed: number,
    whaleAt: number,
    eventLen: number,
    market: MarketEvent | null,
    bossAt: number,
  ): void {
    const rng = this.rng;
    const put = (x: number, y: number, moon = false, bag = false) => {
      const c = this.candles[Math.floor(x)];
      if (!c || c.coins.length >= 6) return;
      c.coins.push(moon ? { x, y, moon } : bag ? { x, y, bag } : { x, y });
    };
    for (let s = 0; s < slots.length; s++) {
      const sl = slots[s];
      const i = start + s;
      const top = surf[s];
      const before = s > 0 ? surf[s - 1] : top;
      if (sl.feature === 'wall') {
        put(i - 0.5, before + 1.2);
        put(i + 0.4, top + 0.6);
      } else if (sl.feature === 'drop') {
        for (const t of [0.12, 0.24]) {
          const y = before - (GRAVITY / 2) * t * t + 0.4;
          if (y > top + 0.4) put(i + 0.1 + speed * t, y);
        }
      } else if (sl.feature === 'spike') {
        put(i + 0.5, top + sl.spike + 0.6);
        if (!slots[s - 1]?.spike) put(i - 0.4, before + 0.9);
        if (!slots[s + 1]?.spike) put(i + 1.4, (surf[s + 1] ?? top) + 0.9);
      } else if (sl.feature === 'gap') {
        let w = 1;
        let a = s;
        while (slots[a - 1]?.gap) a--;
        while (slots[a + w]?.gap) w++;
        put(i + 0.5, top + 1.2 + 0.4 * Math.sin((Math.PI * (s - a + 0.5)) / w));
      } else if (sl.feature === 'fud') {
        put(i + 0.5, top + 0.45);
      } else if (sl.feature === 'paw') {
        // along the low way through
        put(i + 0.5, top + 0.75);
      } else if (sl.feature === 'flyer') {
        // over a jet's back where it meets the player; over a bullet and a bombed gap, along the jump
        put(i + 0.5, top + (sl.flyer > 0 ? sl.flyer + FLYER_H + 0.75 : 1.25));
      } else if (sl.feature === 'bear') {
        // the way down onto the bear
        put(i - 0.3, top + 2.1);
        put(i + 0.5, top + 1.7);
      }
    }

    // an airdrop: a money bag every few candles, at different heights, never on or right beside
    // something dangerous (a bag hanging next to a FUD cloud would be bait)
    if (market === 'airdrop') {
      const risky = (s: number) => {
        const sl = slots[s];
        return (
          !sl ||
          sl.gap ||
          sl.fud ||
          sl.spike > 0 ||
          sl.bear ||
          sl.flyer > 0 ||
          sl.bullet > 0 ||
          sl.event !== null ||
          sl.item !== null
        );
      };
      let s = 1 + this.int(2);
      while (s < eventLen) {
        if (risky(s) || slots[s - 1]?.fud || slots[s + 1]?.fud) {
          s++;
          continue;
        }
        put(start + s + 0.5, surf[s] + BAG_HEIGHTS[this.int(BAG_HEIGHTS.length)], false, true);
        s += 2 + this.int(2);
      }
    }

    // the way up and onto the big bear's head
    if (bossAt >= 0) {
      const top = surf[bossAt];
      put(start + bossAt - 0.9, top + 1.3);
      put(start + bossAt + 0.1, top + BOSS_H + 0.6);
      put(start + bossAt + BOSS_W / 2, top + BOSS_H + 0.9);
    }

    if (whaleAt >= 0) {
      const back = surf[whaleAt + 1];
      const first = start + whaleAt + 1;
      // a row over the back for the ordinary bounces, and a higher row for the held ones
      for (let q = 0; q < WHALE_BACK; q++) put(first + q + 0.5, back + 1.7);
      for (let q = 2; q < WHALE_BACK + 1; q++) put(first + q + 0.5, back + 3.1);
      // moon coins along the way up from the blowhole
      const x0 = first + WHALE_BLOWHOLE + 0.5;
      for (const t of [0.2, 0.3, 0.41, 0.52, 0.62])
        put(x0 + speed * t, back + WHALE_SPOUT * t - (GRAVITY / 2) * t * t + 0.4, true);
    }

    // after a rocket: coins weaving through the sky, and moon coins hidden at the very top
    for (let s = 0; s < slots.length; s++) {
      const i = start + s;
      if (i < this.skyFrom || i >= this.skyTo) continue;
      const top = this.ceiling(i);
      const y = surf[s] + SKY_COIN_ALT + 1.3 * Math.sin(i * 0.55);
      if (y < top - 2.5) put(i + 0.5, y);
      if (i >= this.skyFrom + 3) put(i + 0.5, top + 0.3, true);
    }

    // lines of coins along the quiet stretches
    let s = 0;
    while (s < slots.length) {
      if (slots[s].open && rng() < 0.35) {
        const len = 3 + this.int(3);
        let q = s;
        for (; q < s + len && slots[q]?.open; q++) put(start + q + 0.5, surf[q] + 0.45);
        s = q + 1;
      } else s++;
    }
  }
}

/** where an item floats */
export const itemPos = (c: Candle): Coin => ({ x: c.i + 0.5, y: c.top + ITEM_HEIGHT });
