// The game simulation. Pure logic, no DOM, fixed time step, so it is deterministic and testable.
// One input: is the button held. On the ground it is the jump; in rocket flight it is the throttle.
import { type Candle, Chart, itemPos } from './chart.ts';
import {
  AIR_JUMPS,
  AIR_SQUEEZE_PROFIT,
  BAG_FOMO,
  BAG_PROFIT,
  BEAR_H,
  BEAR_HALF_W,
  BIG_SQUEEZE_FOMO,
  BIG_SQUEEZE_PROFIT,
  BOMB_NOTICE,
  BOSS_H,
  BOSS_STOMP_DEPTH,
  BOSS_V,
  BOSS_W,
  BULL_DIST,
  BULL_GRACE,
  BULL_MAGNET,
  BULL_MULT,
  BULL_REACH,
  BULL_TOSS,
  BULLET_HALF_H,
  BULLET_HALF_W,
  bulletAlt,
  bulletX,
  CANDLE_PROFIT,
  CHAIN_MAX,
  COIN_R,
  COYOTE,
  coinProfit,
  FALL_DEPTH,
  FLYER_BOUNCE,
  FLYER_H,
  FLYER_HALF_W,
  FLYER_WARN,
  FOMO_COIN,
  FOMO_GRAZE,
  FOMO_STOMP,
  FUD_R,
  fireLead,
  flyerX,
  GATE_HEIGHT,
  GATE_MARGIN_RELIEF,
  GRAVITY,
  GRAZE,
  GRAZE_PROFIT,
  hitMargin,
  INVULN,
  INVULN_RESCUE,
  ITEM_R,
  type ItemKind,
  JUMP_BUFFER,
  JUMP_CUT,
  JUMP_MIN_TIME,
  JUMP_V,
  JUMP2_V,
  leverageAt,
  MARGIN_PACK,
  type MarketEvent,
  MOON_PROFIT,
  marketSpeed,
  PAW_FLOOR,
  type Phase,
  PLAYER_H,
  PLAYER_HALF_W,
  ROCKET_DOWN,
  ROCKET_FUEL,
  ROCKET_GRAVITY,
  ROCKET_LAUNCH,
  ROCKET_LAUNCH_V,
  ROCKET_MAGNET,
  ROCKET_SPEED,
  ROCKET_THRUST,
  ROCKET_UP,
  SMASH_PROFIT,
  SPIKE_FORGIVE,
  SPIKE_W,
  SPOUT_HALF,
  SPOUT_MAGNET,
  SQUEEZE_PROFIT,
  type Squad,
  START_X,
  STEP,
  STOMP_DEPTH,
  STOMP_V,
  speedAt,
  TOSS_PROFIT,
  tempo,
  WALL_HOP,
  WHALE_BOUNCE,
  WHALE_BOUNCE_HI,
  WHALE_SPOUT,
  WHALE_WARN,
  WICK_STRIKE,
  WICKS_GRAZE,
} from './data.ts';

/**
 * wall = ran into a tall candle, spike = wicked, slip = fell through a liquidity gap,
 * fud = flew into FUD, bear = ran into a short seller (on the ground or in a jet),
 * bullet = shot by a jet
 */
export type HitReason = 'wall' | 'spike' | 'slip' | 'fud' | 'bear' | 'paw' | 'bullet';

export type SimEvent =
  | { t: 'jump'; air: boolean }
  | { t: 'land' }
  /** a coin picked up; `moon` = a moon coin, `bag` = an airdropped money bag */
  | { t: 'coin'; x: number; y: number; gain: number; moon: boolean; bag: boolean }
  | { t: 'item'; kind: ItemKind }
  | { t: 'hit'; reason: HitReason; shielded: boolean }
  /**
   * short squeeze: landed on a bear. `air` = on a jet, `chain` = how many in a row without
   * touching the ground (1 = the first)
   */
  | { t: 'stomp'; x: number; y: number; gain: number; big: boolean; air: boolean; chain: number }
  /** jets are a few candles away, coming in from the right: which formation */
  | { t: 'flyer'; squad: Squad }
  /** a jet just fired its bullet */
  | { t: 'shot' }
  /** a bomb just blew a candle out of the chart, a few candles ahead */
  | { t: 'bomb' }
  /** in a wick storm: a wick just struck its candle out of the sky, a few candles ahead */
  | { t: 'strike' }
  /** the bull threw the rider up with its horns as the charge ended */
  | { t: 'toss'; gain: number }
  /** a hazard broken during a bull run */
  | { t: 'smash'; reason: HitReason; gain: number }
  /** a close call over the tip of a wick */
  | { t: 'graze'; gain: number }
  | { t: 'bull'; on: boolean }
  /** a whale is a few candles ahead */
  | { t: 'whale' }
  /** bounced off the whale's back; `spout` = off the blowhole, `high` = with the button held */
  | { t: 'bounce'; spout: boolean; high: boolean }
  | { t: 'bank'; amount: number }
  | { t: 'skip'; tier: number }
  /** rocket flight started or ended */
  | { t: 'rocket'; on: boolean }
  /** the tank just ran dry: the flight goes on, falling */
  | { t: 'fuel' }
  | { t: 'phase'; phase: Phase }
  /** a market event started (or, with null, ended) */
  | { t: 'market'; kind: MarketEvent | null }
  | { t: 'liquidated'; lost: number };

/** how a run ended: liquidated by the market, or ended by the player from the pause menu */
export type EndReason = 'liquidated' | 'quit';

export class Run {
  readonly chart: Chart;
  x = START_X;
  y = 0;
  vy = 0;
  grounded = true;
  time = 0;

  private held = false;
  private buffer = 0;
  private coyote = 0;
  private airJumps = AIR_JUMPS;
  private cut = true;
  private jumpAge = 0;

  /** seconds of safety left after a hit */
  invuln = 0;
  /** diamond hands: blocks the next hit */
  shield = false;

  /** thrown up by the whale's spout and not yet down: coins are pulled in */
  spouted = false;
  /** in rocket flight: it ends when the player touches the ground */
  flying = false;
  /** seconds of lift-off left: the rocket climbs by itself */
  launch = 0;
  /** seconds of thrust left in the tank */
  fuel = 0;
  /** is the engine burning this step (for the flame and the sound) */
  thrusting = false;

  /** margin ratio in percent; 100 = liquidation */
  margin = 0;
  /** leverage tier: 0 = 1x, one up for every gate held; it has no cap */
  tier = 0;
  maxTier = 0;
  /** banked at take-profit gates: this is the score */
  realized = 0;
  /** earned since the last take-profit; lost on liquidation */
  unrealized = 0;
  /** what liquidation wiped out */
  lost = 0;

  /** FOMO gauge, 0..100; when it fills, a bull run starts */
  fomo = 0;
  /** candles of bull run left */
  bull = 0;

  coins = 0;
  /** moon coins among them */
  moons = 0;
  hits = 0;
  banks = 0;
  skips = 0;
  /** short squeezes (bears landed on) and hazards smashed in a bull run */
  stomps = 0;
  smashes = 0;
  grazes = 0;
  bulls = 0;
  over = false;
  end: EndReason | null = null;
  phase: Phase;
  /** the market event the player is in, if any */
  market: MarketEvent | null = null;

  /**
   * picked-up coins and items and broken hazards, keyed by candle index * 8 + slot
   * (0-5 = coins, 6 = the hazard on that candle is gone, 7 = the item)
   */
  private taken = new Set<number>();
  /** short squeezes since the player last stood on the ground */
  chain = 0;
  /** the candle whose hazard was broken last: a look-ahead copy has no record of its own */
  private lastBroken = -1;
  private lastGraze = -1;
  /** a look-ahead copy: shares the pickup record and never picks anything up */
  private ghost = false;
  events: SimEvent[] = [];

  constructor(seed: number, chart?: Chart) {
    this.chart = chart ?? new Chart(seed);
    const c = this.chart.at(Math.floor(this.x));
    this.y = c.top;
    this.phase = c.phase;
  }

  get leverage(): number {
    return leverageAt(this.tier);
  }
  /**
   * how fast the game clock runs: faster with every leverage tier (see data.ts), and it never slows
   * down again. Taking profit puts the leverage back to 1x but keeps the speed of the highest tier
   * this run has reached.
   */
  get tempo(): number {
    return tempo(this.maxTier);
  }
  /** candles passed */
  get dist(): number {
    return Math.floor(this.x - START_X);
  }
  get speed(): number {
    return speedAt(this.x) * (this.flying ? ROCKET_SPEED : 1) * marketSpeed(this.market);
  }
  /** what everything earned is multiplied by: leverage, doubled during a bull run */
  get mult(): number {
    return this.leverage * (this.bull > 0 ? BULL_MULT : 1);
  }
  isTaken(i: number, slot: number): boolean {
    return this.taken.has(i * 8 + slot);
  }

  /**
   * An independent copy on the same chart. A ghost copy is cheap and skips pickups: it only answers
   * "what happens to the player if this input is played".
   */
  clone(ghost = false): Run {
    const r: Run = Object.assign(Object.create(Run.prototype), this);
    r.ghost = ghost;
    if (!ghost) r.taken = new Set(this.taken);
    r.events = [];
    return r;
  }

  /** end the run from the pause menu: only realized profit counts */
  quit(): void {
    if (this.over) return;
    this.over = true;
    this.end = 'quit';
  }

  step(dt: number, jumpHeld: boolean): void {
    if (this.over) return;
    this.time += dt;
    if (jumpHeld && !this.held) this.buffer = JUMP_BUFFER;
    else this.buffer = Math.max(0, this.buffer - dt);
    this.held = jumpHeld;
    this.invuln = Math.max(0, this.invuln - dt);

    const x0 = this.x;
    const x1 = x0 + this.speed * dt;
    const i0 = Math.floor(x0);
    const i1 = Math.floor(x1);
    this.x = x1;

    if (this.flying) {
      for (let j = i0 + 1; j <= i1; j++) this.enter(j);
      this.fly(dt, i1);
    } else {
      this.tryJump();
      if (i1 !== i0) this.enter(i1);
      if (this.over) return;
      this.fall(dt, i1);
      if (this.over) return;
      this.hazards();
      if (this.over) return;
    }
    // a gate counts the same on foot and in flight: under it banks, over it holds
    this.gate(x0, x1, i1);
    if (!this.ghost) this.collect(i1);
    if (this.bull > 0) {
      this.bull -= x1 - x0;
      if (this.bull <= 0) this.endBull(i1);
    }
    if (this.grounded || this.flying) this.spouted = false;
    this.callBull();
  }

  /**
   * The bull's charge is over. With the button held it throws the rider up with its horns, which
   * pays; otherwise it just sets the rider down. Either way there is a moment of safety.
   */
  private endBull(i: number): void {
    this.bull = 0;
    if (this.held && !this.flying) {
      this.vy = BULL_TOSS;
      this.grounded = false;
      this.coyote = 0;
      this.cut = true;
      this.airJumps = AIR_JUMPS;
      this.invuln = Math.max(this.invuln, INVULN_RESCUE);
      const gain = TOSS_PROFIT * this.mult;
      this.unrealized += gain;
      this.events.push({ t: 'toss', gain });
    } else {
      this.invuln = Math.max(this.invuln, BULL_GRACE);
      // the bull carried the rider over a gap: now there is nothing underfoot
      if (this.grounded && this.chart.at(i).gap) this.leaveGround();
    }
    this.events.push({ t: 'bull', on: false });
  }

  /** fill the FOMO gauge; a full gauge calls the bull */
  private addFomo(n: number): void {
    if (this.bull > 0) return;
    this.fomo = Math.min(100, this.fomo + n);
  }

  /**
   * A full gauge starts a bull run, but only once the rider is on the ground: the bull has to be
   * able to pick its rider up. In the air or on a rocket the gauge stays full and waits.
   */
  private callBull(): void {
    if (this.fomo < 100 || this.bull > 0 || this.flying || !this.grounded || this.over) return;
    this.fomo = 0;
    this.bull = BULL_DIST;
    this.bulls++;
    this.events.push({ t: 'bull', on: true });
  }

  /** is the hazard on candle i gone (squeezed or smashed) */
  private broken(i: number): boolean {
    return i === this.lastBroken || this.taken.has(i * 8 + 6);
  }
  private breakAt(i: number): void {
    this.lastBroken = i;
    if (!this.ghost) this.taken.add(i * 8 + 6);
  }

  private tryJump(): void {
    if (this.buffer > 0) {
      if (this.grounded || this.coyote > 0) {
        this.vy = JUMP_V;
        this.grounded = false;
        this.coyote = 0;
        this.buffer = 0;
        this.cut = false;
        this.jumpAge = 0;
        this.airJumps = AIR_JUMPS;
        this.events.push({ t: 'jump', air: false });
      } else if (this.airJumps > 0) {
        this.vy = JUMP2_V;
        this.airJumps--;
        this.buffer = 0;
        this.cut = false;
        this.jumpAge = 0;
        this.events.push({ t: 'jump', air: true });
      }
    }
  }

  /** crossing into candle j */
  private enter(j: number): void {
    const c = this.chart.at(j);
    this.unrealized += CANDLE_PROFIT * this.mult;
    if (c.phase !== this.phase) {
      this.phase = c.phase;
      this.events.push({ t: 'phase', phase: c.phase });
    }
    if (c.market !== this.market) {
      this.market = c.market;
      this.events.push({ t: 'market', kind: c.market });
    }
    if (
      this.chart.at(j + WHALE_WARN).event === 'whale' &&
      this.chart.at(j + WHALE_WARN - 1).event !== 'whale'
    )
      this.events.push({ t: 'whale' });
    // jets on the way in (one call for a whole formation), a shot fired, a bomb going off
    const squad = this.chart.at(j + FLYER_WARN).squad;
    if (squad) this.events.push({ t: 'flyer', squad });
    for (let q = 1; q <= 4; q++) {
      const b = this.chart.at(j + q).bullet;
      if (b > 0 && q === Math.ceil(fireLead(b))) this.events.push({ t: 'shot' });
    }
    if (this.chart.at(j + BOMB_NOTICE).crater && !this.chart.at(j + BOMB_NOTICE - 1).crater)
      this.events.push({ t: 'bomb' });
    const wick = this.chart.at(j + WICK_STRIKE);
    if (wick.spike > 0 && wick.market === 'wicks') this.events.push({ t: 'strike' });
    if (this.flying) return;
    // (the bull charges straight across a gap, at the level of the edge before it)
    if (c.gap && this.bull === 0) {
      if (this.grounded) this.leaveGround();
      return;
    }
    const up = c.top - this.y;
    if (this.grounded) {
      if (up > STEP) this.wall(c);
      else if (up >= -STEP) this.y = c.top;
      else this.leaveGround();
    } else if (up > 0) {
      if (up <= STEP) {
        this.y = c.top;
        if (this.vy <= 0) this.touch(c);
      } else this.wall(c);
    }
  }

  private leaveGround(): void {
    this.grounded = false;
    this.coyote = COYOTE;
    this.vy = 0;
    this.cut = true;
  }

  /** came down on candle c: land, or bounce if it is the whale's back */
  private touch(c: Candle): void {
    this.spouted = false;
    if (!c.bounce) {
      this.vy = 0;
      this.grounded = true;
      this.chain = 0;
      this.airJumps = AIR_JUMPS;
      this.events.push({ t: 'land' });
      return;
    }
    // holding the button bounces higher, and on the spout (the blowhole and the candles next to
    // it) it throws the player highest of all; with the button up it is a low bounce everywhere
    const high = this.held;
    let spout = false;
    if (high)
      for (let d = -SPOUT_HALF; d <= SPOUT_HALF; d++)
        if (this.chart.at(c.i + d).spout) spout = true;
    this.vy = spout ? WHALE_SPOUT : high ? WHALE_BOUNCE_HI : WHALE_BOUNCE;
    this.spouted = spout;
    this.grounded = false;
    this.coyote = 0;
    this.cut = true;
    this.airJumps = AIR_JUMPS;
    this.events.push({ t: 'bounce', spout, high });
  }

  /** ran into the side of a candle: take the hit and get pushed on top of it */
  private wall(c: Candle): void {
    this.hurt(this.chart.at(c.i - 1).gap ? 'slip' : 'wall');
    this.y = c.top;
    this.vy = WALL_HOP;
    this.grounded = false;
    this.cut = true;
    this.airJumps = AIR_JUMPS;
  }

  private fall(dt: number, i: number): void {
    if (this.grounded) return;
    this.coyote = Math.max(0, this.coyote - dt);
    this.jumpAge += dt;
    if (!this.held && !this.cut && this.vy > 0 && this.jumpAge >= JUMP_MIN_TIME) {
      this.vy *= JUMP_CUT;
      this.cut = true;
    }
    this.vy -= GRAVITY * dt;
    this.y += this.vy * dt;
    const c = this.chart.at(i);
    if (!c.gap || this.bull > 0) {
      if (this.vy <= 0 && this.y <= c.top) {
        this.y = c.top;
        this.touch(c);
      }
      return;
    }
    this.sink(i);
  }

  /** inside a liquidity gap: slipping below both edges costs margin, then the market bounces you out */
  private sink(i: number): void {
    const far = this.chart.solidFrom(i);
    const floor = Math.min(this.chart.solidUpTo(i).top, far.top) - FALL_DEPTH;
    if (this.y >= floor) return;
    if (this.flying) this.endFlight();
    this.hurt('slip');
    this.invuln = Math.max(this.invuln, INVULN_RESCUE);
    this.vy = Math.sqrt(2 * GRAVITY * (far.top + 2.4 - this.y));
    this.cut = true;
    this.airJumps = AIR_JUMPS;
  }

  private hazards(): void {
    const px = this.x;
    const charging = this.bull > 0;
    const reach = charging ? BULL_REACH : 0;
    // the big bear lies across two candles
    for (let j = Math.max(0, Math.floor(px) - BOSS_W); j <= Math.floor(px + 0.4 + reach); j++) {
      const c = this.chart.at(j);
      if (!c.boss || this.broken(j)) continue;
      if (px + PLAYER_HALF_W + reach <= j + 0.1 || px - PLAYER_HALF_W >= j + BOSS_W - 0.1) continue;
      if (charging) {
        this.hurt('bear', j);
        continue;
      }
      if (this.y >= c.top + BOSS_H) continue;
      const onHead = !this.grounded && this.vy < 0 && this.y > c.top + BOSS_H - BOSS_STOMP_DEPTH;
      if (onHead) this.stomp(j, true);
      else this.hurt('bear', j);
      return;
    }
    if (charging) {
      // the bull goes through everything in front of it, whatever its rider is doing
      for (let i = Math.max(0, Math.floor(px - 0.4)); i <= Math.floor(px + reach); i++) {
        const c = this.chart.at(i);
        if (this.broken(i)) continue;
        if (c.paw) this.hurt('paw', i);
        if (c.gap) continue;
        if (c.spike > 0) this.hurt('spike', i);
        else if (c.fud > 0) this.hurt('fud', i);
        else if (c.bear || c.flyer > 0) this.hurt('bear', i);
        else if (c.bullet > 0) this.hurt('bullet', i);
      }
      return;
    }
    for (let i = Math.floor(px - 0.4); i <= Math.floor(px + 0.4); i++) {
      if (i < 0) continue;
      const c = this.chart.at(i);
      if (this.broken(i)) continue;
      const cx = i + 0.5;
      // a paw of the big bear hangs low over its crack: a short hop passes, anything higher is swatted
      if (c.paw && Math.abs(px - cx) < 0.5 + PLAYER_HALF_W && this.y > c.top + PAW_FLOOR) {
        this.hurt('paw', i);
        return;
      }
      if (c.gap) continue;
      if (c.spike > 0 && Math.abs(px - cx) < PLAYER_HALF_W + SPIKE_W / 2) {
        const tip = c.top + c.spike;
        if (this.y < tip - SPIKE_FORGIVE) {
          this.hurt('spike', i);
          return;
        }
        // a close call: just over the tip
        if (this.y < tip + GRAZE && this.lastGraze !== i && this.bull === 0) {
          this.lastGraze = i;
          this.grazes++;
          const gain = GRAZE_PROFIT * (c.market === 'wicks' ? WICKS_GRAZE : 1) * this.mult;
          this.unrealized += gain;
          this.events.push({ t: 'graze', gain });
          this.addFomo(FOMO_GRAZE);
        }
      }
      if (c.fud > 0) {
        const cy = c.top + c.fud;
        const nx = Math.min(px + PLAYER_HALF_W, Math.max(px - PLAYER_HALF_W, cx));
        const ny = Math.min(this.y + PLAYER_H, Math.max(this.y + 0.05, cy));
        if ((nx - cx) ** 2 + (ny - cy) ** 2 < FUD_R * FUD_R) {
          this.hurt('fud', i);
          return;
        }
      }
      if (c.bear && Math.abs(px - cx) < PLAYER_HALF_W + BEAR_HALF_W && this.y < c.top + BEAR_H) {
        const fromAbove = !this.grounded && this.vy < 0 && this.y > c.top + BEAR_H - STOMP_DEPTH;
        if (this.bull === 0 && fromAbove) this.stomp(i);
        else this.hurt('bear', i);
        return;
      }
      // a bullet: it cannot be landed on, only cleared
      if (c.bullet > 0) {
        const ahead = bulletX(i, px) - px;
        const by = c.top + bulletAlt(c.bullet, ahead);
        if (
          Math.abs(ahead) < PLAYER_HALF_W + BULLET_HALF_W &&
          this.y < by + BULLET_HALF_H &&
          this.y + PLAYER_H > by - BULLET_HALF_H
        ) {
          this.hurt('bullet', i);
          return;
        }
      }
      // a jet: it is here only while the player is (see flyerX)
      if (c.flyer > 0) {
        const fy = c.top + c.flyer;
        if (
          Math.abs(flyerX(i, px) - px) < PLAYER_HALF_W + FLYER_HALF_W &&
          this.y < fy + FLYER_H &&
          this.y + PLAYER_H > fy
        ) {
          const fromAbove = !this.grounded && this.vy < 0 && this.y > fy + FLYER_H - STOMP_DEPTH;
          if (fromAbove) this.stomp(i, false, true);
          else this.hurt('bear', i);
          return;
        }
      }
    }
  }

  /**
   * Short squeeze: landed on a bear. It is gone, the player bounces and may jump again.
   * `big` = it was the big bear at the end of a bear market, which bounces higher and pays far more.
   * `air` = it was a jet. Every squeeze after the first without touching the ground pays one
   * time more.
   */
  private stomp(i: number, big = false, air = false): void {
    this.breakAt(i);
    this.vy = big ? BOSS_V : air ? FLYER_BOUNCE : STOMP_V;
    this.cut = true;
    this.airJumps = AIR_JUMPS;
    this.stomps++;
    this.chain++;
    const chain = Math.min(this.chain, CHAIN_MAX);
    const gain =
      (big ? BIG_SQUEEZE_PROFIT : air ? AIR_SQUEEZE_PROFIT : SQUEEZE_PROFIT) * chain * this.mult;
    this.unrealized += gain;
    const c = this.chart.at(i);
    this.events.push({
      t: 'stomp',
      x: air ? flyerX(i, this.x) : i + (big ? BOSS_W / 2 : 0.5),
      y: air ? c.top + c.flyer + FLYER_H / 2 : c.top + (big ? BOSS_H : BEAR_H) / 2,
      gain,
      big,
      air,
      chain,
    });
    this.addFomo(big ? BIG_SQUEEZE_FOMO : FOMO_STOMP);
  }

  /**
   * Something hit the player. `at` is the candle the hazard stands on, if it is one that can break.
   * Returns true if margin was lost.
   */
  private hurt(reason: HitReason, at = -1): boolean {
    if (this.flying || this.over) return false;
    if (this.bull > 0) {
      // a bull run goes straight through: the hazard breaks and pays
      if (at >= 0) this.breakAt(at);
      if (reason !== 'slip') {
        this.smashes++;
        const gain = SMASH_PROFIT * this.mult;
        this.unrealized += gain;
        this.events.push({ t: 'smash', reason, gain });
      }
      return false;
    }
    if (this.invuln > 0) return false;
    this.invuln = INVULN;
    if (this.shield) {
      this.shield = false;
      this.events.push({ t: 'hit', reason, shielded: true });
      return false;
    }
    this.hits++;
    this.margin = Math.min(100, this.margin + hitMargin(this.tier));
    this.events.push({ t: 'hit', reason, shielded: false });
    if (this.margin >= 100) {
      this.lost = this.unrealized;
      this.unrealized = 0;
      this.over = true;
      this.end = 'liquidated';
      this.events.push({ t: 'liquidated', lost: this.lost });
    }
    return true;
  }

  private gate(x0: number, x1: number, i: number): void {
    const c = this.chart.at(i);
    if (!c.gate) return;
    const gx = i + 0.5;
    if (!(x0 < gx && x1 >= gx)) return;
    if (this.y - c.top <= GATE_HEIGHT) {
      // take profit: close the position, bank the gains, start again at 1x
      const amount = this.unrealized;
      this.realized += amount;
      this.unrealized = 0;
      this.tier = 0;
      this.margin = Math.max(0, this.margin - GATE_MARGIN_RELIEF);
      this.banks++;
      this.events.push({ t: 'bank', amount });
    } else {
      // went over: keep holding, one leverage tier up
      this.tier++;
      this.maxTier = Math.max(this.maxTier, this.tier);
      this.skips++;
      this.events.push({ t: 'skip', tier: this.tier });
    }
  }

  /**
   * Rocket flight. It lifts off by itself; after that the button is the throttle: held, it burns fuel
   * and climbs; let go, or with the tank empty, it falls. Touching the ground ends the flight.
   */
  private fly(dt: number, i: number): void {
    const hadFuel = this.fuel > 0;
    if (this.launch > 0) {
      this.launch = Math.max(0, this.launch - dt);
      this.thrusting = true;
      this.vy = ROCKET_LAUNCH_V;
    } else {
      this.thrusting = this.held && this.fuel > 0;
      if (this.thrusting) {
        this.fuel = Math.max(0, this.fuel - dt);
        if (hadFuel && this.fuel === 0) this.events.push({ t: 'fuel' });
      }
      this.vy += (this.thrusting ? ROCKET_THRUST : -ROCKET_GRAVITY) * dt;
      this.vy = Math.min(ROCKET_UP, Math.max(-ROCKET_DOWN, this.vy));
    }
    this.y += this.vy * dt;
    // the top of the sky: no higher, and it follows the ground down gently
    const top = this.chart.ceiling(i);
    if (this.y > top) {
      this.y = Math.max(top, this.y - ROCKET_DOWN * dt);
      this.vy = Math.min(this.vy, 0);
    }
    const c = this.chart.at(i);
    if (c.gap) {
      this.sink(i);
      return;
    }
    if (this.launch === 0 && this.y <= c.top) {
      this.y = c.top;
      this.endFlight();
      this.touch(c);
    } else if (this.y < c.top) this.y = c.top;
  }

  private endFlight(): void {
    this.flying = false;
    this.launch = 0;
    this.fuel = 0;
    this.thrusting = false;
    this.invuln = Math.max(this.invuln, INVULN_RESCUE);
    this.airJumps = AIR_JUMPS;
    this.cut = true;
    this.events.push({ t: 'rocket', on: false });
  }

  private collect(i: number): void {
    const px = this.x;
    const py = this.y + PLAYER_H / 2;
    // a bull run and a rocket pull coins in from further away
    const reach =
      this.bull > 0
        ? BULL_MAGNET
        : this.spouted
          ? SPOUT_MAGNET
          : this.flying
            ? ROCKET_MAGNET
            : COIN_R;
    for (let j = Math.max(0, i - 2); j <= i + 2; j++) {
      const c = this.chart.at(j);
      for (let s = 0; s < c.coins.length; s++) {
        const key = j * 8 + s;
        if (this.taken.has(key)) continue;
        const coin = c.coins[s];
        if ((coin.x - px) ** 2 + (coin.y - py) ** 2 >= reach * reach) continue;
        this.taken.add(key);
        this.coins++;
        const moon = coin.moon === true;
        if (moon) this.moons++;
        const bag = coin.bag === true;
        const gain = (moon ? MOON_PROFIT : bag ? BAG_PROFIT : coinProfit(c.market)) * this.mult;
        this.unrealized += gain;
        this.events.push({ t: 'coin', x: coin.x, y: coin.y, gain, moon, bag });
        this.addFomo(bag ? BAG_FOMO : FOMO_COIN);
      }
      if (c.item && !this.flying && !this.taken.has(j * 8 + 7)) {
        const p = itemPos(c);
        if ((p.x - px) ** 2 + (p.y - py) ** 2 < ITEM_R * ITEM_R) {
          this.taken.add(j * 8 + 7);
          this.take(c.item);
        }
      }
    }
  }

  private take(kind: ItemKind): void {
    if (kind === 'margin') this.margin = Math.max(0, this.margin - MARGIN_PACK);
    else if (kind === 'shield') this.shield = true;
    else {
      this.flying = true;
      this.launch = ROCKET_LAUNCH;
      this.fuel = ROCKET_FUEL;
      this.grounded = false;
      this.chain = 0;
      this.vy = ROCKET_LAUNCH_V;
      this.events.push({ t: 'rocket', on: true });
    }
    this.events.push({ t: 'item', kind });
  }
}
