// K 線衝浪 — UI glue: menu, HUD, pause, end screen, input and the game loop.
// style.css is linked from surfer/index.html.
import { ARCADE_URL, GAME_URL, readArcadeLocale, track } from './arcade.ts';
import { Sfx } from './audio.ts';
import { Chart } from './chart.ts';
import {
  BULL_DIST,
  BULL_MULT,
  DT,
  EVENT_MIX,
  GATE_EVERY,
  GATE_FIRST,
  hitMargin,
  leverageAt,
  type MarketEvent,
} from './data.ts';
import { HEAD_STYLES, headSvg } from './heads.ts';
import { detectLang, dict, fmt, type Lang } from './i18n.ts';
import { Renderer, tierColor } from './render.ts';
import { hashSeed, todayKey } from './rng.ts';
import { loadSave, recordRun, storeSave } from './save.ts';
import { Run, type SimEvent } from './sim.ts';

// ---------------------------------------------------------------- language (picked in the arcade lobby)
const currentLang = (): Lang =>
  detectLang([readArcadeLocale(), new URLSearchParams(location.search).get('lang')]);
const lang = currentLang();
const t = dict(lang);
document.documentElement.lang = lang === 'zh-Hans' ? 'zh-CN' : lang;
document.title = `SNEK ${t.title} | SNEK Arcade`;
window.addEventListener('pageshow', (e) => {
  if (e.persisted && currentLang() !== lang) location.reload();
});

// ---------------------------------------------------------------- page
const GOLD = '#ffc21f';
const RED = '#ff4d5e';
const num = (n: number) => Math.round(n).toLocaleString('en-US');
const esc = (s: string) =>
  s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c] ?? c);
const headUrl = (id: string) => {
  const style = HEAD_STYLES.find((h) => h.id === id) ?? HEAD_STYLES[0];
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(headSvg(style))}`;
};

const app = document.getElementById('app') as HTMLElement;
app.innerHTML = `
<div class="surfer" id="stage">
  <canvas id="cv"></canvas>

  <div class="hud" id="hud" hidden>
    <div class="hud-row">
      <div class="pnl">
        <div class="pnl-main"><span class="lbl">${esc(t.realized)}</span><b id="realized">0</b></div>
        <div class="pnl-sub">
          <span class="lbl">${esc(t.unrealized)}</span><b id="unrealized">+0</b>
          <span class="lev" id="lev">1x</span>
        </div>
      </div>
      <div class="hud-btns">
        <button class="icon-btn" id="btnMute" type="button" aria-label="${esc(t.sound)}"></button>
        <button class="icon-btn" id="btnPause" type="button" aria-label="${esc(t.pause)}">
          <svg viewBox="0 0 24 24" aria-hidden="true"><rect x="6" y="5" width="4" height="14" rx="1"/><rect x="14" y="5" width="4" height="14" rx="1"/></svg>
        </button>
      </div>
    </div>
    <div class="margin" id="margin">
      <span class="lbl" id="marginLbl">${esc(t.margin)}</span>
      <div class="bar"><i id="marginFill"></i></div>
      <b id="marginPct">0%</b>
      <span class="hit-cost" id="hitCost"></span>
    </div>
    <div class="fomo" id="fomo">
      <span class="lbl" id="fomoLbl">${esc(t.fomo)}</span>
      <div class="bar"><i id="fomoFill"></i></div>
    </div>
  </div>

  <div class="ticker" id="ticker" hidden></div>
  <div class="foot" id="foot" hidden><span id="dist"></span><span id="gateIn"></span></div>
  <div class="event" id="event" hidden><b id="eventName"></b><span id="eventLeft"></span></div>
  <div class="tap-hint" id="tapHint" hidden>${esc(t.tapHint)}</div>

  <div class="overlay" id="menu">
    <div class="card menu-card">
      <img class="hero" src="${headUrl('snek')}" alt="" />
      <h1>${esc(t.title)}</h1>
      <div class="subtitle">${esc(t.subtitle)}</div>
      <p class="tagline">${esc(t.tagline)}</p>
      <div class="best" id="menuBest"></div>
      <button class="btn primary" id="btnPlay" type="button">
        ${esc(t.play)}<small>${esc(t.playSub)}</small>
      </button>
      <button class="btn" id="btnDaily" type="button">
        ${esc(t.daily)}<small id="dailySub">${esc(t.dailySub)}</small>
      </button>
      <div class="row">
        <button class="btn ghost" id="btnHowto" type="button">${esc(t.howto)}</button>
        <a class="btn ghost" href="${ARCADE_URL}">${esc(t.backToArcade)}</a>
      </div>
    </div>
  </div>

  <div class="overlay" id="howto" hidden>
    <div class="card howto-card">
      <h2>${esc(t.howtoTitle)}</h2>
      <dl>
        ${t.howtoRows.map(([k, v]) => `<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}
      </dl>
      <button class="btn primary" id="btnHowtoClose" type="button">${esc(t.close)}</button>
    </div>
  </div>

  <div class="overlay" id="pause" hidden>
    <div class="card">
      <h2>${esc(t.paused)}</h2>
      <button class="btn primary" id="btnResume" type="button">${esc(t.resume)}</button>
      <button class="btn" id="btnPauseHowto" type="button">${esc(t.howto)}</button>
      <button class="btn danger" id="btnEnd" type="button">${esc(t.endRun)}</button>
      <p class="note">${esc(t.endRunHint)}</p>
    </div>
  </div>

  <div class="overlay" id="over" hidden>
    <div class="card over-card" id="overCard">
      <h2 id="overTitle"></h2>
      <div class="over-sub" id="overSub"></div>
      <div class="ribbon" id="overRibbon" hidden></div>
      <div class="score">
        <span class="lbl">${esc(t.realizedLabel)}</span>
        <b id="overScore">0</b><em>${esc(t.unit)}</em>
      </div>
      <div class="stats">
        <div class="lost"><span class="lbl">${esc(t.lostLabel)}</span><b id="overLost">0</b></div>
        <div><span class="lbl">${esc(t.candlesLabel)}</span><b id="overCandles">0</b></div>
        <div><span class="lbl">${esc(t.maxLevLabel)}</span><b id="overLev">1x</b></div>
      </div>
      <p class="note" id="overNote"></p>
      <button class="btn primary" id="btnRetry" type="button">${esc(t.retry)}</button>
      <div class="row">
        <button class="btn ghost" id="btnShare" type="button">${esc(t.share)}</button>
        <button class="btn ghost" id="btnMenu" type="button">${esc(t.menu)}</button>
      </div>
    </div>
  </div>
</div>`;

const $ = <T extends HTMLElement = HTMLElement>(id: string) => document.getElementById(id) as T;
const stage = $('stage');
const els = {
  hud: $('hud'),
  realized: $('realized'),
  unrealized: $('unrealized'),
  lev: $('lev'),
  margin: $('margin'),
  marginFill: $('marginFill'),
  marginPct: $('marginPct'),
  hitCost: $('hitCost'),
  marginLbl: $('marginLbl'),
  fomo: $('fomo'),
  fomoLbl: $('fomoLbl'),
  fomoFill: $('fomoFill'),
  event: $('event'),
  eventName: $('eventName'),
  eventLeft: $('eventLeft'),
  ticker: $('ticker'),
  foot: $('foot'),
  dist: $('dist'),
  gateIn: $('gateIn'),
  tapHint: $('tapHint'),
  menu: $('menu'),
  menuBest: $('menuBest'),
  dailySub: $('dailySub'),
  howto: $('howto'),
  pause: $('pause'),
  over: $('over'),
  overCard: $('overCard'),
  overTitle: $('overTitle'),
  overSub: $('overSub'),
  overRibbon: $('overRibbon'),
  overScore: $('overScore'),
  overLost: $('overLost'),
  overCandles: $('overCandles'),
  overLev: $('overLev'),
  overNote: $('overNote'),
  btnMute: $('btnMute'),
};

// ---------------------------------------------------------------- state
type State = 'menu' | 'play' | 'pause' | 'over';
type Mode = 'random' | 'daily';

const save = loadSave();
const sfx = new Sfx();
sfx.muted = save.muted;
const renderer = new Renderer($<HTMLCanvasElement>('cv'));
renderer.labels = { gate: t.gateLabel, hold: t.holdLabel };

let state: State = 'menu';
let mode: Mode = 'random';
let dailyDate: string | null = null;
let run = new Run(hashSeed(`menu-${todayKey()}`));
let held = false;
let acc = 0;
let last = performance.now();
/** when the end screen may appear (the liquidation plays out first) */
let overAt = 0;
/** has the "hold for the horns" prompt been shown for this bull charge */
let bullPrompted = false;
/** the candle where the market event that is on ends */
let eventEnd = 0;
/** the run the jet tips were last shown in, and how often each has been shown */
let flyerTipRun: Run | null = null;
let flyerTips = { plain: 0, gunner: 0, bomber: 0 };
/** when the rocket engine may sound again */
let thrustAt = 0;
/** ignore "start again" key presses until this time, so a held jump key does not restart */
let guardUntil = 0;
let howtoFrom: State = 'menu';
renderer.reset(run);

const show = (el: HTMLElement, on: boolean) => {
  el.hidden = !on;
};

function refreshMenu(): void {
  const today = todayKey();
  const lines = [`${t.best} <b>${num(save.best)}</b> ${esc(t.unit)}`];
  if (save.bestCandles > 0) lines.push(esc(fmt(t.bestCandles, { n: num(save.bestCandles) })));
  els.menuBest.innerHTML = lines.join('<br />');
  els.dailySub.textContent =
    save.daily.date === today && save.daily.best > 0
      ? `${today}｜${fmt(t.dailyBest, { n: num(save.daily.best) })}`
      : `${today}｜${t.dailySub}`;
}

function refreshMute(): void {
  els.btnMute.innerHTML = save.muted
    ? '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 9v6h4l5 4V5L8 9H4z"/><path class="line" d="M16 9l5 6M21 9l-5 6"/></svg>'
    : '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 9v6h4l5 4V5L8 9H4z"/><path class="line" d="M16 8.5a5 5 0 010 7M18.5 6a8.5 8.5 0 010 12"/></svg>';
}

function setState(s: State): void {
  state = s;
  show(els.menu, s === 'menu');
  show(els.pause, s === 'pause');
  show(els.hud, s !== 'menu');
  show(els.foot, s === 'play' || s === 'pause');
  if (s !== 'over') show(els.over, false);
  if (s === 'menu') show(els.event, false);
  if (s !== 'play') {
    held = false;
    show(els.tapHint, false);
  }
  stage.classList.toggle('playing', s === 'play');
}

/**
 * For trying things out on the machine the game is developed on: ?event=wicks (or any other market
 * event) makes it the first event of every random chart. Ignored everywhere else and on the daily chart.
 */
const tryEvent: MarketEvent | null = (() => {
  if (location.hostname !== 'localhost' && location.hostname !== '127.0.0.1') return null;
  const want = new URLSearchParams(location.search).get('event');
  return (EVENT_MIX.find(([kind]) => kind === want)?.[0] ?? null) as MarketEvent | null;
})();

/** Also only there: ?sounds opens a board with every sound effect on its own button. */
if (
  (location.hostname === 'localhost' || location.hostname === '127.0.0.1') &&
  new URLSearchParams(location.search).has('sounds')
)
  void import('./soundboard.ts').then((m) => m.openSoundboard());

function startRun(m: Mode): void {
  mode = m;
  dailyDate = m === 'daily' ? todayKey() : null;
  const seed = dailyDate ? hashSeed(`surfer-${dailyDate}`) : (Math.random() * 2 ** 32) >>> 0;
  run = new Run(seed, tryEvent && !dailyDate ? new Chart(seed, tryEvent) : undefined);
  renderer.reset(run);
  acc = 0;
  last = performance.now();
  hud.reset();
  setState('play');
  show(els.tapHint, save.runs < 3);
  sfx.unlock();
  track.start(m);
}

function pause(): void {
  if (state !== 'play') return;
  setState('pause');
}
function resume(): void {
  if (state !== 'pause') return;
  last = performance.now();
  acc = 0;
  setState('play');
}

function finish(): void {
  const rec = recordRun(save, { realized: run.realized, candles: run.dist, dailyDate });
  storeSave(save);
  track.over({
    score: run.realized,
    candles: run.dist,
    seconds: Math.round(run.time),
    reason: run.end ?? 'quit',
    leverage: leverageAt(run.maxTier),
    mode,
  });
  const rekt = run.end === 'liquidated';
  els.overCard.classList.toggle('rekt', rekt);
  els.overTitle.textContent = rekt ? t.rektTitle : t.quitTitle;
  els.overSub.textContent = rekt ? t.rektSub : t.quitSub;
  els.overNote.textContent = rekt ? t.rektNote : t.quitNote;
  const ribbon = rec.best ? t.newBest : rec.daily ? t.newDaily : '';
  els.overRibbon.textContent = ribbon;
  show(els.overRibbon, ribbon !== '' && run.realized > 0);
  els.overScore.textContent = num(run.realized);
  els.overLost.textContent = num(rekt ? run.lost : run.unrealized);
  els.overCandles.textContent = num(run.dist);
  els.overLev.textContent = `${leverageAt(run.maxTier)}x`;
  show(els.over, true);
  guardUntil = performance.now() + 500;
  refreshMenu();
}

function share(): void {
  const text = fmt(t.shareText, {
    candles: num(run.dist),
    score: num(run.realized),
    lev: leverageAt(run.maxTier),
  });
  const url = `https://x.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(GAME_URL)}`;
  window.open(url, '_blank', 'noopener');
}

function openHowto(from: State): void {
  howtoFrom = from;
  show(els.howto, true);
  if (!save.seenHowto) {
    save.seenHowto = true;
    storeSave(save);
  }
}

// ---------------------------------------------------------------- HUD
let tickerTimer = 0;
function ticker(text: string): void {
  els.ticker.textContent = text;
  show(els.ticker, true);
  els.ticker.classList.remove('in');
  void els.ticker.offsetWidth;
  els.ticker.classList.add('in');
  window.clearTimeout(tickerTimer);
  tickerTimer = window.setTimeout(() => show(els.ticker, false), 2400);
}

const hud = {
  realized: -1,
  unrealized: -1,
  tier: -1,
  margin: -1,
  dist: -1,
  gate: -1,
  fomo: -1,
  bull: false,
  eventLeft: -1,
  reset(): void {
    this.realized = this.unrealized = this.tier = this.margin = this.dist = this.gate = -1;
    this.fomo = -1;
    this.bull = false;
    els.fomo.classList.remove('bull');
    this.eventLeft = -1;
    show(els.event, false);
    els.fomoLbl.textContent = t.fomo;
    show(els.ticker, false);
  },
  update(): void {
    // the FOMO bar lines up under the margin bar, whatever the language
    const lblWidth = els.marginLbl.offsetWidth;
    if (lblWidth) els.fomoLbl.style.minWidth = `${lblWidth}px`;
    // the same bar shows the gauge filling, then the bull run running out
    const bull = run.bull > 0;
    if (bull !== this.bull) {
      this.bull = bull;
      els.fomo.classList.toggle('bull', bull);
      els.fomoLbl.textContent = bull ? t.bullLabel : t.fomo;
    }
    const fomo = Math.round(bull ? (run.bull / BULL_DIST) * 100 : run.fomo);
    if (fomo !== this.fomo) {
      this.fomo = fomo;
      els.fomoFill.style.width = `${fomo}%`;
    }
    // near the end of a bull charge: tell the player what holding the button will do
    if (bull && run.bull < 5 && !bullPrompted) {
      bullPrompted = true;
      ticker(t.bullHold);
    }
    // the market event that is on, and how many candles of it are left
    if (run.market) {
      const left = Math.max(0, Math.ceil(eventEnd - run.x));
      if (left !== this.eventLeft) {
        this.eventLeft = left;
        els.eventLeft.textContent = fmt(t.eventLeft, { n: left });
      }
    }
    if (run.realized !== this.realized) {
      this.realized = run.realized;
      els.realized.textContent = num(run.realized);
    }
    if (run.unrealized !== this.unrealized) {
      this.unrealized = run.unrealized;
      els.unrealized.textContent = `+${num(run.unrealized)}`;
    }
    if (run.tier !== this.tier) {
      this.tier = run.tier;
      els.lev.textContent = `${leverageAt(run.tier)}x`;
      els.lev.style.background = tierColor(run.tier);
      // what a hit costs at this leverage, and how much faster the game runs
      const cost = fmt(t.hitCost, { n: hitMargin(run.tier) });
      els.hitCost.textContent =
        run.maxTier > 0 ? `${cost}｜${fmt(t.tempo, { n: run.tempo.toFixed(2) })}` : cost;
      els.lev.classList.remove('pop');
      void els.lev.offsetWidth;
      els.lev.classList.add('pop');
    }
    if (run.margin !== this.margin) {
      this.margin = run.margin;
      els.marginFill.style.width = `${run.margin}%`;
      els.marginPct.textContent = `${Math.round(run.margin)}%`;
      els.margin.dataset.level = run.margin >= 75 ? 'high' : run.margin >= 50 ? 'mid' : 'low';
    }
    if (run.dist !== this.dist) {
      this.dist = run.dist;
      els.dist.textContent = fmt(t.candles, { n: num(run.dist) });
    }
    const k = Math.max(0, Math.ceil((run.x - 0.5 - GATE_FIRST) / GATE_EVERY));
    const left = Math.ceil(GATE_FIRST + GATE_EVERY * k + 0.5 - run.x);
    if (left !== this.gate) {
      this.gate = left;
      els.gateIn.textContent = fmt(t.gateIn, { n: left });
      els.gateIn.classList.toggle('soon', left <= 6);
    }
  },
};

// ---------------------------------------------------------------- events from the simulation
function handle(ev: SimEvent): void {
  switch (ev.t) {
    case 'jump':
      sfx.jump(ev.air);
      renderer.burst(run.x - 0.2, run.y, '#bfe6ff', ev.air ? 8 : 5, 2.5);
      break;
    case 'coin':
      if (ev.moon) {
        sfx.moon();
        renderer.burst(ev.x, ev.y, '#dff1ff', 12, 5);
      } else if (ev.bag) {
        // a money bag bursts into coins
        sfx.bag();
        renderer.burst(ev.x, ev.y, GOLD, 26, 8);
        renderer.say(run, `+${num(ev.gain)}`, GOLD, 1.1);
      } else {
        sfx.coin();
        renderer.burst(ev.x, ev.y, GOLD, 4, 3);
      }
      break;
    case 'item':
      sfx.item();
      renderer.say(
        run,
        t.item[ev.kind],
        ev.kind === 'margin' ? '#2ee58a' : ev.kind === 'shield' ? '#7ad7ff' : '#ff9f48',
        1.1,
      );
      break;
    case 'hit':
      if (ev.shielded) {
        sfx.block();
        renderer.say(run, t.blocked, '#7ad7ff', 1.1);
        renderer.burst(run.x, run.y + 0.5, '#7ad7ff', 16, 5);
      } else {
        sfx.hit();
        renderer.say(run, t.hit[ev.reason], RED, 1.2);
        renderer.burst(run.x, run.y + 0.5, RED, 18, 6);
        renderer.shakeBy(0.3);
        renderer.flashBy(RED, 0.9);
        navigator.vibrate?.(50);
      }
      break;
    case 'bank':
      sfx.bank();
      renderer.say(run, fmt(t.banked, { n: num(ev.amount) }), GOLD, 1.3);
      renderer.burst(run.x, run.y + 0.8, GOLD, 26, 7);
      renderer.flashBy(GOLD, 0.5);
      ticker(t.bankedTip);
      break;
    case 'skip':
      sfx.skip(ev.tier);
      renderer.say(run, fmt(t.held, { n: leverageAt(ev.tier) }), tierColor(ev.tier), 1.3);
      renderer.burst(run.x, run.y + 0.5, tierColor(ev.tier), 20, 6);
      break;
    case 'rocket':
      if (ev.on) {
        sfx.rocket();
        ticker(t.rocketTip);
      }
      break;
    case 'fuel':
      sfx.block();
      renderer.say(run, t.fuelOut, '#ff9f48', 1.1);
      break;
    case 'bounce':
      sfx.bounce(ev.spout);
      renderer.burst(run.x, run.y, '#bfe6ff', ev.spout ? 34 : 14, ev.spout ? 9 : 5);
      if (ev.spout) {
        renderer.say(run, t.spout, '#7db8ff', 1.4);
        renderer.shakeBy(0.15);
      }
      break;
    case 'stomp':
      if (ev.big) {
        // the big bear at the end of a bear market
        sfx.bigStomp();
        renderer.say(run, fmt(t.bigSqueeze, { n: num(ev.gain) }), '#2ee58a', 1.6);
        renderer.burst(ev.x, ev.y, RED, 60, 10);
        renderer.burst(ev.x, ev.y, GOLD, 30, 8);
        renderer.shakeBy(0.35);
        renderer.flashBy('#2ee58a', 0.6);
        navigator.vibrate?.([40, 30, 80]);
      } else {
        sfx.stomp(ev.chain);
        renderer.say(
          run,
          ev.chain > 1
            ? fmt(t.chainSqueeze, { k: ev.chain, n: num(ev.gain) })
            : fmt(t.squeeze, { n: num(ev.gain) }),
          ev.chain > 1 ? GOLD : '#2ee58a',
          Math.min(1.6, 1.1 + 0.15 * ev.chain),
        );
        renderer.burst(ev.x, ev.y, RED, 22, 6);
        if (ev.chain > 1) renderer.burst(ev.x, ev.y, GOLD, 10 + 6 * ev.chain, 7);
        renderer.shakeBy(0.12);
        navigator.vibrate?.(20);
      }
      break;
    case 'toss':
      sfx.toss();
      renderer.say(run, fmt(t.toss, { n: num(ev.gain) }), GOLD, 1.5);
      renderer.burst(run.x, run.y + 0.5, GOLD, 36, 9);
      renderer.shakeBy(0.15);
      break;
    case 'smash':
      sfx.smash();
      renderer.say(run, fmt(t.smash, { n: num(ev.gain) }), GOLD, 1.1);
      renderer.burst(run.x + 0.3, run.y + 0.5, GOLD, 18, 7);
      renderer.shakeBy(0.12);
      break;
    case 'graze':
      sfx.graze();
      renderer.say(run, fmt(t.graze, { n: num(ev.gain) }), '#ffe9ec', 1);
      break;
    case 'bull':
      if (ev.on) {
        sfx.bull();
        renderer.say(run, t.bullOn, GOLD, 1.5);
        renderer.burst(run.x, run.y + 0.5, GOLD, 40, 9);
        renderer.flashBy(GOLD, 0.7);
        ticker(fmt(t.bullTip, { n: BULL_DIST, x: BULL_MULT }));
        bullPrompted = false;
      } else ticker(t.bullOff);
      break;
    case 'whale':
      sfx.whale();
      ticker(t.whaleTip);
      break;
    case 'flyer':
      sfx.flyer();
      // the words only for the first few of a run: after that the beeps and the arrow say enough
      if (flyerTipRun !== run) {
        flyerTipRun = run;
        flyerTips = { plain: 0, gunner: 0, bomber: 0 };
      }
      {
        const kind = ev.squad === 'gunner' || ev.squad === 'bomber' ? ev.squad : 'plain';
        if (flyerTips[kind]++ < 3)
          ticker(kind === 'gunner' ? t.gunTip : kind === 'bomber' ? t.bombTip : t.flyerTip);
      }
      break;
    case 'shot':
      sfx.shot();
      break;
    case 'strike':
      sfx.strike();
      break;
    case 'bomb':
      sfx.bomb();
      navigator.vibrate?.(30);
      break;
    case 'phase':
      ticker(`${t.phase[ev.phase]}｜${t.phaseTip[ev.phase]}`);
      break;
    case 'market':
      show(els.event, ev.kind !== null);
      if (ev.kind) {
        // the event runs to the end of this block
        let end = Math.floor(run.x);
        while (run.chart.at(end).market === ev.kind) end++;
        eventEnd = end;
        const good = ev.kind !== 'exit' && ev.kind !== 'bearmarket';
        els.event.dataset.kind = ev.kind;
        els.eventName.textContent = t.market[ev.kind];
        sfx.market(good);
        renderer.say(run, t.market[ev.kind], good ? GOLD : RED, 1.5);
        renderer.flashBy(good ? GOLD : RED, 0.5);
        ticker(`${t.market[ev.kind]}｜${t.marketTip[ev.kind]}`);
      } else ticker(t.marketEnd);
      break;
    case 'liquidated':
      sfx.liquidated();
      renderer.burst(run.x, run.y + 0.5, RED, 60, 10);
      renderer.burst(run.x, run.y + 0.5, GOLD, 30, 7);
      renderer.shakeBy(0.6);
      renderer.flashBy(RED, 1);
      navigator.vibrate?.([80, 60, 160]);
      break;
    case 'land':
      break;
  }
}

// ---------------------------------------------------------------- loop
function frame(now: number): void {
  const dt = Math.min(0.1, (now - last) / 1000);
  last = now;
  if (state === 'play') {
    // the higher the leverage, the faster the clock: more steps of the same simulation per second
    acc += dt * run.tempo;
    while (acc >= DT && !run.over) {
      run.step(DT, held);
      acc -= DT;
      if (run.events.length) {
        for (const ev of run.events) handle(ev);
        run.events.length = 0;
      }
    }
    if (run.time > 3) show(els.tapHint, false);
    // the engine: a short burst of noise for as long as it burns
    if (run.flying && run.thrusting && now >= thrustAt) {
      sfx.thrust();
      thrustAt = now + 90;
    }
    hud.update();
    if (run.over) {
      setState('over');
      overAt = now + 1000;
    }
  } else if (state === 'over' && overAt && now >= overAt) {
    overAt = 0;
    finish();
  }
  renderer.draw(run, now / 1000, state === 'pause' ? 0 : dt, state === 'play');
  requestAnimationFrame(frame);
}

// ---------------------------------------------------------------- input
const JUMP_KEYS = new Set(['Space', 'ArrowUp', 'KeyW', 'KeyX']);

stage.addEventListener('pointerdown', (e) => {
  if (state !== 'play') return;
  if ((e.target as Element).closest('button, a')) return;
  e.preventDefault();
  held = true;
  sfx.unlock();
});
for (const type of ['pointerup', 'pointercancel'] as const)
  window.addEventListener(type, () => {
    held = false;
  });
window.addEventListener('blur', () => {
  held = false;
});
stage.addEventListener('contextmenu', (e) => e.preventDefault());

window.addEventListener('keydown', (e) => {
  if (e.code === 'KeyP' || e.code === 'Escape') {
    if (!els.howto.hidden) closeHowto();
    else if (state === 'play') pause();
    else if (state === 'pause') resume();
    return;
  }
  const go = JUMP_KEYS.has(e.code) || e.code === 'Enter';
  if (!go) return;
  e.preventDefault();
  if (e.repeat) return;
  if (!els.howto.hidden) return;
  if (state === 'play') {
    if (JUMP_KEYS.has(e.code)) {
      held = true;
      sfx.unlock();
    }
  } else if (state === 'menu') startRun('random');
  else if (state === 'pause') resume();
  else if (state === 'over' && !els.over.hidden && performance.now() > guardUntil) startRun(mode);
});
window.addEventListener('keyup', (e) => {
  if (JUMP_KEYS.has(e.code)) held = false;
});

document.addEventListener('visibilitychange', () => {
  if (document.hidden) pause();
});
window.addEventListener('resize', () => renderer.resize());

function closeHowto(): void {
  show(els.howto, false);
  if (howtoFrom === 'pause') last = performance.now();
}

$('btnPlay').addEventListener('click', () => startRun('random'));
$('btnDaily').addEventListener('click', () => startRun('daily'));
$('btnHowto').addEventListener('click', () => openHowto('menu'));
$('btnPauseHowto').addEventListener('click', () => openHowto('pause'));
$('btnHowtoClose').addEventListener('click', closeHowto);
$('btnPause').addEventListener('click', pause);
$('btnResume').addEventListener('click', resume);
$('btnEnd').addEventListener('click', () => {
  run.quit();
  setState('over');
  finish();
});
$('btnRetry').addEventListener('click', () => startRun(mode));
$('btnShare').addEventListener('click', share);
$('btnMenu').addEventListener('click', () => {
  run = new Run(hashSeed(`menu-${todayKey()}`));
  renderer.reset(run);
  setState('menu');
});
els.btnMute.addEventListener('click', () => {
  save.muted = !save.muted;
  sfx.muted = save.muted;
  storeSave(save);
  refreshMute();
  sfx.unlock();
});

refreshMenu();
refreshMute();
setState('menu');
track.pageView();
requestAnimationFrame(frame);
// first visit: show the rules once
if (!save.seenHowto) openHowto('menu');
