// The moon in the sky. Its surface is computed per pixel on the GPU (no texture): maria, three layers
// of craters with real bowls and rims, ray systems from a couple of young craters, lunar-style shading
// with a soft terminator and faint earthshine. It is the same surface as the moon in SNEK Merge,
// drawn here with plain WebGL (no three.js) into a small canvas of its own, which the 2D renderer
// then paints into the sky. It slowly spins.
//
// Without WebGL `ready` stays false and the renderer falls back to a flat disc.

const SPIN = 0.05; // rad/s, about two minutes per turn
/** a slight axial tilt so the spin reads as a real rotation, not a slide */
const TILT = { x: 0.32, y: 0.6, z: 0.1 };
/** sunlight direction in view space: from the upper left, slightly in front -> waxing gibbous */
const LIGHT = norm([-0.72, 0.36, 0.6]);
/** the disc fills this much of the canvas; the rest is room for the soft edge */
export const MOON_FILL = 0.96;

function norm(v: number[]): number[] {
  const l = Math.hypot(v[0], v[1], v[2]);
  return [v[0] / l, v[1] / l, v[2] / l];
}

const VERT = /* glsl */ `
attribute vec2 aPos;
varying vec2 vUv;
void main() {
  vUv = aPos;
  gl_Position = vec4(aPos, 0.0, 1.0);
}`;

const FRAG = /* glsl */ `
uniform mat3 uInv;    // view space -> the moon's own space
uniform vec3 uLight;  // in the moon's own space
uniform vec3 uView;   // in the moon's own space
uniform float uPx;    // one pixel, in units of the disc radius
varying vec2 vUv;

vec3 hash33(vec3 p) {
  p = fract(p * vec3(0.1031, 0.1030, 0.0973));
  p += dot(p, p.yxz + 33.33);
  return fract((p.xxy + p.yxx) * p.zyx);
}
float hash13(vec3 p) {
  p = fract(p * 0.1031);
  p += dot(p, p.zyx + 31.32);
  return fract((p.x + p.y) * p.z);
}
float vnoise(vec3 p) {
  vec3 i = floor(p);
  vec3 f = fract(p);
  vec3 u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(mix(hash13(i), hash13(i + vec3(1, 0, 0)), u.x), mix(hash13(i + vec3(0, 1, 0)), hash13(i + vec3(1, 1, 0)), u.x), u.y),
    mix(mix(hash13(i + vec3(0, 0, 1)), hash13(i + vec3(1, 0, 1)), u.x), mix(hash13(i + vec3(0, 1, 1)), hash13(i + vec3(1, 1, 1)), u.x), u.y),
    u.z);
}
float fbm(vec3 p, int oct) {
  float a = 0.5;
  float s = 0.0;
  for (int i = 0; i < 6; i++) {
    if (i >= oct) break;
    s += a * vnoise(p);
    p = p * 2.03 + 17.1;
    a *= 0.5;
  }
  return s;
}

// one layer of craters scattered through 3D cells; returns height in sphere units
float craterLayer(vec3 p, float scale, float density, inout float fresh) {
  vec3 q = p * scale;
  vec3 i = floor(q);
  vec3 f = fract(q);
  float h = 0.0;
  for (int x = -1; x <= 1; x++)
  for (int y = -1; y <= 1; y++)
  for (int z = -1; z <= 1; z++) {
    vec3 c = i + vec3(x, y, z);
    vec3 r = hash33(c);
    if (r.x > density) continue;
    vec3 center = vec3(x, y, z) + 0.15 + 0.7 * hash33(c + 11.7);
    float rad = 0.12 + 0.4 * r.y * r.y * r.y;
    float d = length(f - center) / rad;
    if (d > 1.7) continue;
    float bowl = (d * d - 1.0) * 0.42 * (1.0 - smoothstep(0.7, 1.02, d));
    float floorFlat = smoothstep(0.0, 0.45, d); // larger craters get flatter floors
    float rim = 0.2 * exp(-pow((d - 1.0) * 2.8, 2.0));
    float ejecta = 0.05 * (1.0 - smoothstep(1.0, 1.7, d));
    h += (bowl * mix(1.0, floorFlat, r.y) + rim + ejecta) * rad / scale;
    fresh += step(0.86, r.z) * (1.0 - smoothstep(0.0, 1.5, d)) * 0.8;
  }
  return h;
}

// footprint-aware height: tiny craters fade out when the moon is small (no shimmer)
float heightAt(vec3 p, float fp, float mare, inout float fresh) {
  float w2 = smoothstep(1.5 * fp, 5.0 * fp, 1.0 / 8.0);
  float w3 = smoothstep(1.5 * fp, 5.0 * fp, 1.0 / 19.0);
  float f1 = 0.0, f2 = 0.0, f3 = 0.0;
  float h = craterLayer(p, 3.0, 0.3, f1);
  h += craterLayer(p + 3.1, 8.0, 0.32, f2) * w2;
  h += craterLayer(p + 7.7, 19.0, 0.4, f3) * w3;
  h *= mix(1.0, 0.5, mare); // maria are smoother
  h += (fbm(p * 5.0, 4) - 0.5) * 0.02;            // rolling terrain
  h += (fbm(p * 30.0, 3) - 0.5) * 0.004 * w3;
  fresh = f1 + f2 * 0.7 * w2 + f3 * 0.4 * w3;
  return h;
}

float rays(vec3 n, vec3 R, float seed) {
  float c = dot(n, R);
  float ang = acos(clamp(c, -1.0, 1.0));
  if (ang > 1.1) return 0.0;
  vec3 a = normalize(cross(R, abs(R.y) < 0.9 ? vec3(0, 1, 0) : vec3(1, 0, 0)));
  vec3 b = cross(R, a);
  vec3 t = n - R * c;
  float phi = atan(dot(t, b), dot(t, a));
  float s = vnoise(vec3(cos(phi) * 9.0, sin(phi) * 9.0, seed));
  s = pow(s, 4.0) * 2.0;
  return s * pow(smoothstep(1.1, 0.05, ang), 2.0) * smoothstep(0.02, 0.07, ang);
}

// the tone curve and colour space SNEK Merge renders with (ACES filmic, exposure 1.05, sRGB)
vec3 fit(vec3 v) {
  vec3 a = v * (v + 0.0245786) - 0.000090537;
  vec3 b = v * (0.983729 * v + 0.4329510) + 0.238081;
  return a / b;
}
vec3 aces(vec3 color) {
  const mat3 inMat = mat3(
    vec3(0.59719, 0.07600, 0.02840), vec3(0.35458, 0.90834, 0.13383), vec3(0.04823, 0.01566, 0.83777));
  const mat3 outMat = mat3(
    vec3(1.60475, -0.10208, -0.00327), vec3(-0.53108, 1.10813, -0.07276), vec3(-0.07367, -0.00605, 1.07602));
  color *= 1.05 / 0.6;
  return clamp(outMat * fit(inMat * color), 0.0, 1.0);
}
vec3 toSrgb(vec3 c) {
  return mix(c * 12.92, 1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, step(0.0031308, c));
}

void main() {
  // the disc: an orthographic view of a unit sphere
  vec2 q = vUv / ${MOON_FILL.toFixed(2)};
  float r = length(q);
  float alpha = 1.0 - smoothstep(1.0 - 1.5 * uPx, 1.0, r);
  if (alpha <= 0.0) {
    gl_FragColor = vec4(0.0);
    return;
  }
  float rr = min(r, 0.9995);
  vec3 vPos = uInv * vec3(q / max(r, 1e-5) * rr, sqrt(1.0 - rr * rr));

  vec3 n = normalize(vPos);
  float fp = length(fwidth(vPos));

  // maria: big dark basalt plains, mostly on one hemisphere
  float mare = smoothstep(0.44, 0.56, fbm(n * 1.5 + vec3(4.2, 1.3, 7.7), 5) + 0.06 * fbm(n * 6.0, 3));
  mare *= smoothstep(-0.35, 0.45, dot(n, normalize(vec3(0.25, 0.15, 1.0))));

  // bumped normal from central differences on the tangent plane
  vec3 t1 = normalize(cross(n, abs(n.y) < 0.99 ? vec3(0, 1, 0) : vec3(1, 0, 0)));
  vec3 t2 = cross(n, t1);
  float e = max(0.0012, fp * 0.6);
  float fresh = 0.0, tmp = 0.0;
  float h0 = heightAt(n, fp, mare, fresh);
  float h1 = heightAt(normalize(n + t1 * e), fp, mare, tmp);
  float h2 = heightAt(normalize(n + t2 * e), fp, mare, tmp);
  vec3 grad = (h1 - h0) / e * t1 + (h2 - h0) / e * t2;
  vec3 N = normalize(n - grad * 0.95);

  // albedo (sRGB-ish values, converted to linear below)
  vec3 high = vec3(0.70, 0.69, 0.665);
  vec3 sea = vec3(0.30, 0.305, 0.33);
  vec3 alb = mix(high, sea, mare * 0.92);
  alb *= 0.82 + 0.34 * fbm(n * 6.0 + 2.0, 5);
  alb *= 0.93 + 0.14 * fbm(n * 40.0, 2);
  alb += fresh * 0.05;
  alb += rays(n, normalize(vec3(-0.25, -0.5, 0.83)), 3.0) * 0.07;
  alb += rays(n, normalize(vec3(0.55, 0.3, 0.78)), 9.0) * 0.05;
  alb = clamp(alb, 0.0, 1.0);
  vec3 albLin = pow(alb, vec3(2.2));

  // lunar-ish shading: Lambert blended with Lommel-Seeliger (flat-ish disc), soft terminator
  vec3 L = normalize(uLight);
  vec3 V = normalize(uView - vPos);
  float cosi = max(dot(N, L), 0.0);
  float cose = max(dot(N, V), 0.0);
  float ls = cosi / (cosi + cose + 1e-4);
  float diff = mix(cosi, 2.0 * ls, 0.5);
  float term = smoothstep(-0.06, 0.16, dot(n, L));
  vec3 col = albLin * diff * term * 1.15;
  col += albLin * vec3(0.035, 0.05, 0.07) * (1.0 - term);       // earthshine
  float limb = pow(1.0 - max(dot(n, V), 0.0), 3.0);
  col += vec3(0.55, 0.85, 0.75) * limb * 0.10;                    // faint cool rim, matches the halo

  col = toSrgb(aces(col));
  gl_FragColor = vec4(col * alpha, alpha);
}`;

type GL = WebGLRenderingContext | WebGL2RenderingContext;

export class Moon {
  /** what the 2D renderer paints: a square canvas with the disc in the middle */
  readonly canvas: HTMLCanvasElement;
  /** false without WebGL: nothing was drawn and nothing will be */
  ready = false;
  private gl: GL | null = null;
  private uInv: WebGLUniformLocation | null = null;
  private uLight: WebGLUniformLocation | null = null;
  private uView: WebGLUniformLocation | null = null;
  private uPx: WebGLUniformLocation | null = null;
  private drawnAt = Number.NEGATIVE_INFINITY;

  constructor() {
    this.canvas = document.createElement('canvas');
    this.canvas.width = this.canvas.height = 2;
    try {
      this.setUp();
    } catch {
      this.ready = false;
    }
    this.canvas.addEventListener('webglcontextlost', () => {
      this.ready = false;
    });
  }

  private setUp(): void {
    const opts: WebGLContextAttributes = {
      alpha: true,
      premultipliedAlpha: true,
      antialias: false,
      depth: false,
      stencil: false,
      preserveDrawingBuffer: true,
      powerPreference: 'low-power',
    };
    const gl2 = this.canvas.getContext('webgl2', opts);
    const gl: GL | null = gl2 ?? this.canvas.getContext('webgl', opts);
    if (!gl) return;
    let vert = VERT;
    let frag = `precision highp float;\n${FRAG}`;
    if (gl2) {
      // the same source, spelled the WebGL 2 way
      vert = `#version 300 es\n#define attribute in\n#define varying out\n${VERT}`;
      frag = `#version 300 es\nprecision highp float;\n#define varying in\nout vec4 fragColor;\n#define gl_FragColor fragColor\n${FRAG}`;
    } else {
      // fwidth is an extension in WebGL 1
      if (!gl.getExtension('OES_standard_derivatives')) return;
      frag = `#extension GL_OES_standard_derivatives : enable\n${frag}`;
    }
    const compile = (type: number, src: string) => {
      const sh = gl.createShader(type);
      if (!sh) throw new Error('no shader');
      gl.shaderSource(sh, src);
      gl.compileShader(sh);
      if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS))
        throw new Error(gl.getShaderInfoLog(sh) ?? 'shader');
      return sh;
    };
    const prog = gl.createProgram();
    if (!prog) return;
    gl.attachShader(prog, compile(gl.VERTEX_SHADER, vert));
    gl.attachShader(prog, compile(gl.FRAGMENT_SHADER, frag));
    gl.bindAttribLocation(prog, 0, 'aPos');
    gl.linkProgram(prog);
    if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) return;
    gl.useProgram(prog);
    gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
    this.uInv = gl.getUniformLocation(prog, 'uInv');
    this.uLight = gl.getUniformLocation(prog, 'uLight');
    this.uView = gl.getUniformLocation(prog, 'uView');
    this.uPx = gl.getUniformLocation(prog, 'uPx');
    this.gl = gl;
    this.ready = true;
  }

  /**
   * Draw the moon as it looks at time `t` (seconds), `size` device pixels across. It turns slowly,
   * so it is only redrawn a few times a second, or when the size changes.
   */
  update(size: number, t: number): void {
    const gl = this.gl;
    if (!gl || !this.ready) return;
    const px = Math.max(16, Math.min(512, Math.round(size)));
    const resized = this.canvas.width !== px;
    if (!resized && Math.abs(t - this.drawnAt) < 0.15) return;
    this.drawnAt = t;
    if (resized) this.canvas.width = this.canvas.height = px;
    gl.viewport(0, 0, px, px);

    // rotation of the moon (Euler XYZ), as three.js builds it; `inv` is its transpose
    const a = Math.cos(TILT.x);
    const b = Math.sin(TILT.x);
    const c = Math.cos(TILT.y + t * SPIN);
    const d = Math.sin(TILT.y + t * SPIN);
    const e = Math.cos(TILT.z);
    const f = Math.sin(TILT.z);
    const m = [
      [c * e, -c * f, d],
      [a * f + b * e * d, a * e - b * f * d, -b * c],
      [b * f - a * e * d, b * e + a * f * d, a * c],
    ];
    // view -> local is the transpose; a GLSL mat3 is filled column by column
    const inv = new Float32Array([
      m[0][0],
      m[0][1],
      m[0][2],
      m[1][0],
      m[1][1],
      m[1][2],
      m[2][0],
      m[2][1],
      m[2][2],
    ]);
    const toLocal = (v: number[]) => [
      m[0][0] * v[0] + m[1][0] * v[1] + m[2][0] * v[2],
      m[0][1] * v[0] + m[1][1] * v[1] + m[2][1] * v[2],
      m[0][2] * v[0] + m[1][2] * v[1] + m[2][2] * v[2],
    ];
    gl.uniformMatrix3fv(this.uInv, false, inv);
    gl.uniform3fv(this.uLight, toLocal(LIGHT));
    gl.uniform3fv(this.uView, toLocal([0, 0, 30]));
    gl.uniform1f(this.uPx, 2 / (px * MOON_FILL));
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
  }
}
